\newrgbcolor{qqwuqq}{0. 0.39215686274509803 0.}
\newrgbcolor{ccqqqq}{0.8 0. 0.}
\psset{xunit=0.7cm,yunit=0.7cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1.6pt,arrowsize=3pt 2,arrowinset=0.25}
