\begin{scriptsize}
\psaxes[xAxis=true,yAxis=true,Dx=5.,Dy=2.,ticksize=-2pt 0,subticks=0]{->}(0,0)(-3.322727272727277,-1.6690909090908792)(71.04772727272733,12.96)[$t$ (in Tagen),140] [$v(t)$ (in cm/Tag),-40]
\psline(0.,0.)(40.,4.)
\psline(40.,4.)(50.,4.)
