\Subitem{Ein Punkt für das Angeben der beiden richtigen Werte.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Begründen.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$\dfrac{u(75)-u(50)}{75-50}=\dfrac{2,465-1,256}{25}=0,048\ldots$\vspace{0,3cm}

Die durchschnittliche Zunahme zwischen 50 und 75 Jahren beträgt rund 0,05\,m pro Jahr.} %Lösung von Unterpunkt1
\Subitem{Die momentane Wachstumsrate zum Zeitpunkt $t=50$ beträgt 0,043\,m pro Jahr.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
