Gegeben ist die Funktion $f\!:\mathbb{R}\rightarrow\mathbb{R}$ mit $f(x)=e^x$.%Aufgabentext

\begin{aufgabenstellung}
\item Gegeben ist eine lineare Funktion $g_1\!:\mathbb{R}\rightarrow\mathbb{R}$ mit $g_1(x)=k\cdot x+2$ und $k\in\mathbb{R}$.%Aufgabentext

\Subitem{Gib alle $k\in\mathbb{R}$ an, für die die Graphen von $f$ und $g_1$ einander in genau zwei Punkten schneiden.} %Unterpunkt1

Für ein solches $k$ beschreibt die Funktion $h\!:\mathbb{R}\rightarrow\mathbb{R}$ mit $h(x)=g_1(x)-f(x)$ die Differenz von $g_1$ und $f$. Für eine Stelle $x_0$ zwischen den beiden Schnittpunkten der Graphen gilt die Beziehung $h'(x_0)=0$.

\Subitem{Bestimme $x_0$ in Abhängigkeit von $k$.} %Unterpunkt2

\item Der Graph einer linearen Funktion $g_2\!:\mathbb{R}\rightarrow\mathbb{R}$ mit $g_2(x)=4\cdot x+d$ und $d\in\mathbb{R}$ ist eine Tangente an den Graphen von $f$.%Aufgabentext

\Subitem{Gib die Koordinaten des Berührpunkts $B$ der beiden Graphen an.} %Unterpunkt1
\Subitem{Gib den Wert von $d$ an.} %Unterpunkt2

\item Gegeben ist die Funktion $g_3\!:\mathbb{R}\rightarrow\mathbb{R}$ mit $g_3(x)=1$.\\
	Die von den beiden Graphen von $g_3$ und $f$ im Intervall $[a;0]$ (mit $a\in\mathbb{R}$ und $a<0$) eingeschlossene Fläche $I$ hat den Flächeninhalt $A_1$. Die von den beiden Graphen von $f$ und $g_3$ im Intervall $[0;1]$ eingeschlossene Fläche $II$ hat den Flächeninhalt $A_2$.
	\begin{center}	\psset{xunit=2.0cm,yunit=1.05cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=0.8pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-1.4897368421052626,-0.4)(1.8621710526315782,7.88)
\multips(0,0)(0,1.0){9}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(-1.4897368421052626,0)(1.8621710526315782,0)}
\multips(-1,0)(1.0,0){4}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,0)(0,7.88)}
\psaxes[labelFontSize=\scriptstyle,showorigin=false,xAxis=true,yAxis=true,Dx=1.,Dy=1.,ticksize=-2pt 0,subticks=0]{->}(0,0)(-1.4897368421052626,-0.4)(1.8621710526315782,7.88)[x,140] [\text{$f(x),g_3(x)$},-40]
\pscustom[linewidth=0.8pt,fillcolor=black,fillstyle=solid,opacity=0.1]{\psplot{-0.75}{1.}{2.718281828459045^(x)}\lineto(1.,1.)\psplot{1.}{-0.75}{1.0}\lineto(-0.75,0.47236655274101474)\closepath}
\psplot[linewidth=1.pt,plotpoints=200]{-1.4897368421052626}{1.8621710526315782}{2.718281828459045^(x)}
\psplot[linewidth=1.pt,plotpoints=200]{-1.4897368421052626}{1.8621710526315782}{1.0}
\psline[linewidth=1.pt](-0.75,1.)(-0.75,0.)
\begin{scriptsize}
\rput[tl](0.684473684210526,1.64){II}
\rput[tl](-0.5938815789473681,0.82){I}
\rput[bl](1.35,5){$f$}
\rput[bl](-0.6744078947368418,1.14){$g_3$}
\rput[bl](-0.765,-0.18){$a$}
\end{scriptsize}
\end{pspicture*}
	\end{center}%Aufgabentext

\Subitem{Berechne den Flächeninhalt $A_2$.} %Unterpunkt1
\Subitem{Drücke das bestimmte Integral $\displaystyle\int^1_a(f(x)-g_3(x))\dx$ durch die Flächeninhalte $A_1$ und $A_2$ aus.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$k\in\mathbb{R}^+$	} %Lösung von Unterpunkt1
\Subitem{möglicher Vorgehensweise:\\
	$h(x)=g_1(x)-f(x)=k\cdot x+2-e^x$\\
	$h'(x)=k-e^x$\\
	$h'(x_0)=0 \Rightarrow k-e^{x_0}=0 \Rightarrow x_0=\ln(k)$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung. Andere Schreibweisen der Lösung sind ebenfalls als richtig zu werten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung. Andere Schreibweisen der Lösung sind ebenfalls als richtig zu werten.

	Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{mögliche Vorgehensweise:\\
	$B=(x_B\mid f(x_B))$\\
	$f'(x_B)=4$\\
	$e^{x_B}=4 \Rightarrow x_B=\ln(4)$\\
	$f(x_B)=e^{\ln(4)}=4$\\
	$B=(\ln(4)\mid 4)$} %Lösung von Unterpunkt1
\Subitem{$4=4\cdot\ln(4)+d \Rightarrow d=4-4\cdot\ln(4)\approx-1,545$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die Angabe der beiden richtigen Koordinaten.

	Toleranzintervall für $x_B\!:[1,3;1,4]$\\
	Toleranzintervall für $f(x_B)\!:[3,6;4,1]$\\
	Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung.

	Toleranzintervall für $d\!:[-2,0;-1,1]$\\
	Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$A_3=\displaystyle\int^1_0(e^x-1)\,\text{d}x=e-2$} %Lösung von Unterpunkt1
\Subitem{$\displaystyle\int^1_a(f(x)-g_3(x))\,\text{d}x=A_2-A_1$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die richtige Lösung, wobei bereits die Angabe $\displaystyle\int^1_0(e^x-1)\,\text{d}x$ als richtig zu werten ist.

	Toleranzintervall: $[0,70;0,72]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung. Äquivalente Ausdrücke sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

