	$P(Y=y)$&\antwort{$0,2$}&\antwort{$0,3$}&\antwort{$0,4$}&\antwort{$0,1$}\\ \hline
	\end{tabular}%Aufgabentext

\Subitem{Vervollständige die Gewinne.} %Unterpunkt1
\Subitem{Vervollständige die Wahrscheinlichkeiten.} %Unterpunkt2

