\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$\displaystyle\int^{10}_0 -\frac{3}{100}t^3+\frac{9}{20}t^2\,\text{d}t+15\cdot 35+\frac{15\cdot 15}{2}=75+525+112,5+=712,5$} %Lösung von Unterpunkt1
