				A5=0,  % 5. Antwort
				}}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$G=400-207=193$, $p=38\,\%, A=? \Rightarrow A=400\cdot 0,38=73,34$

Zwischen 73 und 74 männliche Jugendlichen verwendeten \textit{TikTok}} %Lösung von Unterpunkt1
\Subitem{$400\cdot 0,17=68$

Insgesamt haben 68 Jugendliche die Plattform verwendet: 25 Mädchen und 43 Burschen.} %%Lösung von Unterpunkt2

