\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Das Integral $\int^5_0{v(t)}dt$ gibt die Länge des Weges in Metern an, den das Fahrzeug in den ersten fünf Sekunden seiner Bewegung zurücklegt.} %Lösung von Unterpunkt1
\Subitem{Der Ausdruck $\dfrac{\int^5_0{v(t)dt}-\int^2_0{v(t)dt}}{3}$ gibt die durchschnittliche Geschwindigkeit in m/s des Fahrzeugs im Zeitintervall $[2;5]$ an.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Interpretation. Die Antwort muss die Einheit m und das Zeitintervall beinhalten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Deutung. Äquivalente Formulierungen sind zu akzeptieren.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$v(t)=-0,8t^2+8t$\\
	$v'(t)=-1,6t+8$\\
	$v'(3)=3,2$

	Die Beschleunigung 3 Sekunden nach dem Beginn der Bewegung beträgt 3,2\,m/$\text{s}^2$.} %Lösung von Unterpunkt1
\Subitem{Die Beschleunigung nimmt pro Sekunde um 1,6\,m/$\text{s}^2$ ab.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Wert und eine dementsprechende Interpretation. Der Zeitpunkt und der Begriff "`Beschleunigung"' müssen angegeben werden.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für den richtigen Wert und eine dementsprechende Interpretation. Die Einheit m/$\text{s}^2$ muss angegeben werden.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$v(t)=-0,8t^2+8t=20$\\
$-0,8t^2+8t-20=0$ \hspace*{1cm} $t_1=t_2=5$} %Lösung von Unterpunkt1
\Subitem{Die Geschwindigkeit steigt im gegebenen Zeitintervall an und erreicht nach 5 Sekunden ihr Maximum von 20 m/s.

Skizzen von Parabeln, die diese Aussage belegen, und äquivalente Formulierungen sind ebenfalls
als richtig zu werten.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Berechnung des Zeitpunkts.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine korrekte Beschreibung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$A=90=15\cdot 1+\frac{15\cdot t}{2}$

Der Bremsweg wird in 10 Sekunden zurückgelegt.} %Lösung von Unterpunkt1
\Subitem{Graphik: siehe oben.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Bremsweg.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für den richtig eingezeichneten Anhalteweg.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

