Die Dachsteinseilbahn erschließt vom oberösterreichischen Ort Obertraun aus den nördlichen Teil des Dachsteinmassivs. Die Dachsteinseilbahn besteht aus drei Teilstrecken. Die erste Teilstrecke auf die Schönbergalm ist bereits seit 1951 in Betrieb. Die zweite Teilstrecke führt von der Schönbergalm zum Krippenstein. Von dort aus ist die Aussichtsplattform \textit{five fingers} durch einen Fußweg erreichbar. Die dritte Teilstrecke führt vom Krippenstein weiter zur Gjaidalm. 

				Bei den folgenden Aufgabenstellungen werden Orte als Punkte modelliert. %Aufgabentext

\begin{aufgabenstellung}
\item Die Bergstation Krippenstein $K_1$ und die Schönbergalm $S$ sind durch eine Seilbahn verbunden. Der Verlauf des Tragseils wird, wie in der nebenstehenden Abbildung dargestellt, modelliert. Dabei werden $x$ und $y$ in Metern gemessen.


	\begin{center}
	\resizebox{0.5\linewidth}{!}{\includegraphics{../_database/Bilder/Bild41-1.eps}}
	\end{center}

	Nach dieser Modellierung gilt: $K=(0\mid 2\,100)$ und $S=(2\,160\mid 1\,350)$%Aufgabentext

\Subitem{Bestimme den Steigungswinkel des Tragseils.} %Unterpunkt1
\Subitem{An welcher Stelle gleicher Seehöhe wie $S$ müsste die Talstation $S'$ stehen, wenn das Tragseil mit $100\,\%$ Steigung verlaufen soll?

	Gib die Koordinaten von $S'$ an.} %Unterpunkt2

	\item Mit zunehmender Höhe nimmt der Luftdruck exponentiell ab. Dabei gilt für die Höhe $h$ (gemessen in m über dem Meeresspiegel) und den Luftdruck $p$ (gemessen in mbar) näherungsweise der folgende funktionale Zusammenhang: $p(h)=1\,013,25\cdot e^{-0,000118\cdot h}$.

\Subitem{Berechne die prozentuelle Druckabnahme auf der Fahrt von der Schönbergalm (Seehöhe $1\,350$\,m) bis zur Bergstation Krippenstein (Seehöhe 2\,100\,m)}
\Subitem{Kreuze die zutreffende(n) Aussage(n) an!\vspace{0,2cm}

		\multiplechoice[5]{  %Anzahl der Antwortmoeglichkeiten, Standard: 5
						L1={Die prozentuelle Druckabnahme pro Höhenmeter ist konstant.},   %1. Antwortmoeglichkeit 
						L2={Bei einer Verdopplung der Höhe halbiert sich der Luftdruck.},   %2. Antwortmoeglichkeit
						L3={Die absolute Druckabnahme pro Höhenmeter ist konstant.},   %3. Antwortmoeglichkeit
						L4={Der zur Funktion $p$ gehörige Graph ist streng monoton fallend.},   %4. Antwortmoeglichkeit
						L5={Der zur Funktion $p$ gehörige Graph nähert sich asymptotisch der waagrechten Achse.},	 %5. Antwortmoeglichkeit
						L6={},	 %6. Antwortmoeglichkeit
						L7={},	 %7. Antwortmoeglichkeit
						L8={},	 %8. Antwortmoeglichkeit
						L9={},	 %9. Antwortmoeglichkeit
						%% LOESUNG: %%
						A1=1,  % 1. Antwort
						A2=4,	 % 2. Antwort
						A3=5,  % 3. Antwort
						A4=0,  % 4. Antwort
						A5=0,  % 5. Antwort
						}}
\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$\tan(\alpha)=\frac{750}{2\,160}\Rightarrow\alpha\approx 19,15^\circ$ bzw. $\alpha\approx 0,3342$\,rad} %Lösung von Unterpunkt1
\Subitem{$S'=(750|1\,350)$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die korrekte Berechnung.

		Lösungsintervall: $[19^\circ;19,2^\circ]$ bzw. $[0,33\,\text{rad};0,335\,\text{rad}]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die korrekte Berechnung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$\dfrac{p(1\,350)-p(2\,100)}{p(1\,350)}\approx 0,085=8,5\,\%$} %Lösung von Unterpunkt1
\Subitem{MC: Lösung siehe oben.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine korrekte Berechnung. Lösungsintervall $[0,084;0,085]$ bzw. $[8,4\,\%;8,5\,\%]$.

	Lösungen aus dem Intervall $[-0,085;-0,084]$ bzw. $[-8,5\,\%;-8,4\,\%]$ sind ebenso als richtig zu werten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Multiple-Choice-Aufgabe: Ein Punkt ist genau dann zu geben, wenn ausschließlich alle laut Lösungserwartung richtigen Antwortmöglichkeiten angekreuzt sind.
} %Lösungschlüssel von Unterpunkt2


\end{loesung}

