\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Entnimm der entsprechenden Grafik, in welchem Zeitintervall die absolute und die relative Abnahme (in Prozent) der bei Verkehrsunfällen getöteten Personen jeweils am größten waren, und gib die entsprechenden Werte an.} %Unterpunkt1
\Subitem{Im vorliegenden Fall fand die größte relative Abnahme der Anzahl der bei Verkehrsunfällen Getöteten in einem anderen Zeitintervall statt als die größte absolute Abnahme. Gib eine mathematische Begründung an, warum die größte relative Abnahme und die größte absolute Abnahme einer Größe oder eines Prozesses nicht im gleichen Zeitintervall stattfinden müssen.} %Unterpunkt2

\item Die Entwicklung des prozentuellen Anteils der Getöteten gemessen an der Gesamtzahl der bei Verkehrsunfällen verunglückten Personen kann für den Zeitraum von Beginn des Jahres 1971 bis Ende 2011 durch eine lineare Funktion $f$ angenähert werden, wobei die Variable $t$ die Anzahl der seit Ende 1970 vergangenen Jahre bezeichnet. %Aufgabentext

\Subitem{Ermittle eine Gleichung dieser Funktion $f$ auf Basis der Daten aus der entsprechenden Grafik im Zeitraum von Beginn des Jahres 1971 bis Ende 2011.} %Unterpunkt1
\Subitem{Gib den theoretisch größtmöglichen Zeitraum an, für den diese Funktion $f$ ein unter der Annahme eines gleichbleibenden Trends geeignetes Modell darstellt.} %Unterpunkt2

\item Im Jahr 1976 wurde in Österreich die Gurtpflicht eingeführt. Seit diesem Zeitpunkt ist man dazu verpflichtet, auf den vorderen Sitzen eines PKW oder Kombis den Sicherheitsgurt anzulegen. Durch die Einführung der Gurtpflicht kam es zu einer deutlichen Abschwächung der Unfallfolgen.%Aufgabentext

\Subitem{Berechne auf Basis der Tabellenwerte für die Jahre 1971 und 1981 die durchschnittliche jährliche Abnahme der Anzahl der Unfälle mit Personenschaden.} %Unterpunkt1
\Subitem{Ein "`Gurtmuffel"' behauptet, dass es auch schon vor der Einführung der Gurtpflicht im Zeitraum zwischen 1961 und 1971 zu einer relativen Abnahme der Verkehrsunfälle mit  Personenschaden kam. Ermittle mithilfe des vorhandenen Datenmaterials Zahlen, die seine Aussage untermauern, und präzisieren Sie diese Aussage.} %Unterpunkt2

\item Die nachstehende Tabelle enthält Daten über Verunglückte im Jahr 2001.

	\begin{center}
		\begin{tabular}{|l|c|c|}\hline
		Verkehrsart&Anzahl der Verletzten&Anzahl der Getöteten\\ \hline
		einspuriges KFZ&8\,605&85\\ \hline
		PKW&24\,853&290\\ \hline
		sonstige&11\,567&148\\ \hline
		\end{tabular}
	\end{center}

	Jemand ist im Jahr 2011 bei einem Verkehrsunfall verunglückt.%Aufgabentext

\Subitem{Gib die relative Häufigkeit als Schätzwert der Wahrscheinlichkeit, dass diese Person mit einem einspurigen KFZ oder einem PKW unterwegs war und den Unfall nicht überlebt hat, an.} %Unterpunkt1
\Subitem{Interpretiere die mit $\frac{24\,853}{25\,143}\approx 0,99$ angegebene Wahrscheinlichkeit im vorliegenden Zusammenhang.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Die größte absolute Abnahme fand im Zeitintervall von 1971 bis 1981 statt (-884), die größte relative Abnahme war in den Jahren von 2001 bis 2011 (-0,454 bzw. -45,4\,\%).} %Lösung von Unterpunkt1
\Subitem{Da für die Berechnung der relativen Abnahme einer Größe auch der Bezugswert entscheidend ist, müssen größte absolute Abnahme und größte relative Abnahme einer Größe oder eines Prozesses nicht im gleichen Zeitintervall stattfinden.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt wird für die korrekten Zeitintervalle und die richtigen Abnahmewerte vergeben.

Toleranzintervall für relative Abnahme: $[-0,46; -0,45]$ bzw. $[-46\,\%; -45\,\%]$; die Vorzeichen müssen nicht angegeben sein.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt wird für eine (sinngemäß) richtige verbale Begründung vergeben. Dabei kann die Begründung auch anhand konkreter Zahlen erfolgen.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$f(t)=-0,065t+3,7$} %Lösung von Unterpunkt1
\Subitem{Diese Funktion kann höchstens 57 Jahre, also bis zum Beginn des Jahres 2028, zur Modellbildung herangezogen werden.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt wird für die Angabe eines korrekten Funktionsterms vergeben. (Der Punkt kann auch vergeben werden, wenn eine andere Variable als $t$ verwendet wird.)  

Toleranzintervall für die ersten Parameter: $[-0,08; -0,05]$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt wird für die Angabe der entsprechenden Zeitspanne und/oder des entsprechenden Jahres vergeben. 

Toleranzintervalle: $[51 \text{ Jahre}; 70 \text{ Jahre}]$, $[2022; 2042]$.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Die Anzahl der Unfälle mit Personenschäden nahm durchschnittlich um 607,3 pro Jahr ab.} %Lösung von Unterpunkt1
\Subitem{Anzahl der Unfälle mit Personenschaden pro tausend KFZ:

			\begin{itemize}
				\item 1961: 30 (berechneter Wert liegt bei $\approx 29,9$)
				\item 1971: 23 (berechneter Wert liegt bei $\approx 22,5$)
			\end{itemize}

			Bezogen auf die Anzahl der zugelassenen KFZ hat die Anzahl der Unfälle mit Personenschaden also tatsächlich abgenommen.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt wird für die korrekte Angabe der durchschnittlichen jährlichen Abnahme vergeben.

Toleranzintervall: $[600; 610]$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt wird für das Heranziehen des entsprechenden Datenmaterials und eine korrekte Berechnung vergeben. Die Aussage kann auch anhand der relativen Werte präzisiert werden. } %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{\begin{tabular}{|l|c|c|c|}\hline
			Verkehrsart&Anzahl der Verletzten&Anzahl der Getöteten&\cellcolor[gray]{0.9}Summe\\ \hline
			einspuriges KFZ&8\,605&85&\cellcolor[gray]{0.9}8\,690\\ \hline
			PKW&24\,853&290&\cellcolor[gray]{0.9}25\,143\\ \hline
			sonstiges&11\,567&148&\cellcolor[gray]{0.9}11\,715\\ \hline
			\cellcolor[gray]{0.9}Summe&\cellcolor[gray]{0.9}45\,025&\cellcolor[gray]{0.9}523&\cellcolor[gray]{0.9}45\,548\\ \hline			
			\end{tabular}

			$\frac{(85+290)}{45\,548}\approx 0,008$

			Die gesuchte Wahrscheinlichkeit beträgt ca. 0,8\,\%.} %Lösung von Unterpunkt1
\Subitem{Die Wahrscheinlichkeit, den Unfall zu überleben, wenn man mit einem PKW verunglückt, beträgt 99\,\%.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt wird für die richtige Angabe der Wahrscheinlichkeit vergeben. 

Toleranzintervall: $[0,008; 0,0083]$ bzw. $[0,8\,\%; 0,83\,\%]$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt wird für eine (sinngemäß) korrekte Interpretation vergeben.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

130.content:
Beim Ein- bzw. Ausatmen wird Luft in unsere Lungen gesaugt bzw. wieder aus ihnen herausgepresst. Ein Atemzyklus erstreckt sich über den gesamten Vorgang des einmaligen Einatmens und anschließenden Ausatmens. Während des Atemvorganges lässt sich das bewegte Luftvolumen messen. Der Luftstrom wird in Litern pro Sekunde angegeben. 

				Der Luftstrom $L(t)$ kann in Abhängigkeit von der Zeit $t$ ($t$ in Sekunden) näherungsweise durch die Sinusfunktion $L$ beschrieben werden. Ein Atemzyklus beginnt zum Zeitpunkt $t = 0$ mit dem Einatmen. Nach einer Messung kann der Atemvorgang einer bestimmten Person modellhaft durch folgende Sinusfunktion beschrieben werden: 

				$$L(t)=0,6\cdot\sin\left(\frac{\pi}{2}\cdot t\right)$$%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Ermittle die Periodenlänge der gegebenen Funktion $L$.

	Die Periodenlänge beträgt \antwort[\rule{3cm}{0.3pt}]{4\,} Skunden.} %Unterpunkt1
\Subitem{Erkläre die Bedeutung der Periodenlänge in Bezug auf den Atemvorgang.} %Unterpunkt2

\item %Aufgabentext

\Subitem{Berechne $\displaystyle\int^2_0{L(t)}$d$t$ und runde das Ergebnis auf zwei Nachkommastellen.} %Unterpunkt1
\Subitem{Beschreibe für das in Diskussion stehende Problem, was mit dem oben stehenden mathematischen Ausdruck berechnet wird.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Die Periodenlänge beträgt 4 Sekunden.} %Lösung von Unterpunkt1
\Subitem{Die Periodenlänge gibt die Zeitdauer eines Atemzyklus (= einmal Einatmen und einmal Ausatmen) an.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die korrekte Ermittlung der Periodenlänge. Es genügt dabei die Angabe des gesuchten Wertes, eine Rechnung oder Zeichnung ist nicht erforderlich.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine (sinngemäß) korrekte Deutung der Periodenlänge. Zulässig sind auch andere sinngemäß richtige Antworten, die auf den Atemvorgang konkret Bezug nehmen. Ohne konkreten Bezug zum gegebenen Kontext ist die Antwort nicht als korrekt zu werten.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$\displaystyle\int^2_0{L(t)}dt=\int^2_0{0,6\sin\left(\frac{\pi}{2}\cdot t\right)}dt=\left(-0,6\cdot \frac{2}{\pi}\cdot \cos\left(\frac{\pi}{2}\cdot t\right)\right)\bigg|^2_0\approx 0,76$} %Lösung von Unterpunkt1
\Subitem{Durch das bestimmte Integral wird das gesamte Luftvolumen (in Litern) berechnet, das während des Einatmens (in den ersten beiden Sekunden) in die Lunge strömt.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die richtige Lösung. 

Toleranzintervall: $[0,76; 0,80]$. Die Einheit muss beim Ergebnis nicht zwingend angeführt werden.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine (sinngemäß) korrekte Interpretation. Zulässig sind auch andere sinngemäß richtige Antworten, die auf den Atemvorgang konkret Bezug nehmen.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

131.content:
In der Leichtathletik gibt es für Läufer/innen spezielle Trainingsmethoden. Dazu werden Trainingspläne erstellt. Es ist dabei sinnvoll, bei Trainingsläufen Teilzeiten zu stoppen, um Stärken und Schwächen der Läuferin/des Läufers zu analysieren.

				Zur Erstellung eines Trainingsplans für eine Läuferin wurden die Teilzeiten während eines Trainingslaufs gestoppt. Für die 200 Meter lange Laufstrecke wurden bei diesem Trainingslauf 26,04 Sekunden gemessen. Im nachstehenden Diagramm ist der zurückgelegte Weg $s(t)$ in Abhängigkeit von der Zeit $t$ für diesen Trainingslauf mithilfe einer Polynomfunktion $s$ vom Grad 3 modellhaft dargestellt. 

Für die Funktion s gilt die Gleichung $s(t)=-\frac{7}{450}t^3+0,7t^2$ ($s(t)$ in Metern, $t$ in Sekunden).

\begin{center}
\psset{xunit=0.5cm,yunit=0.03cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=4pt 0,linewidth=0.8pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-1.3003333333333276,-15.000024096443592)(27.03033333333324,215.60051951932385)
\multips(0,0)(0,20.0){12}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,0)(27.03033333333324,0)}
\multips(0,0)(2.0,0){15}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,0)(0,215.60051951932385)}
\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,Dx=2.,Dy=20.,ticksize=-2pt 0,subticks=0]{->}(0,0)(0.,0.)(27.03033333333324,215.60051951932385)
\psplot[linewidth=1.2pt,plotpoints=200]{0}{26}{(-7)/450*x^(3)+0.7*x^(2)}
\rput[tl](13.88866666666662,110.800266988595){s}
\rput[tl](0.525666666666666,207.20049927831124){$s(t)$ in m}
\rput[tl](23.508666666666578,13.600023132585848){$t$ in s}
\end{pspicture*}
\end{center}%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Berechne die Wendestelle der Funktion $s$} %Unterpunkt1
\Subitem{Interpretiere die Bedeutung der Wendestelle in Bezug auf die Geschwindigkeit der Läuferin} %Unterpunkt2

\item %Aufgabentext

\Subitem{Bestimme die mittlere Geschwindigkeit der Läuferin für die 200 Meter lange Laufstrecke in Metern pro Sekunde.} %Unterpunkt1
\Subitem{Der Mittelwertsatz der Differenzialrechnung besagt, dass unter bestimmten Voraussetzungen in einem Intervall $[a;b]$ für eine Funktion $f$ mindestens ein $x_0\in(a;b)$ existiert, sodass $f'(x_0)=\frac{f(b)-f(a)}{b-a}$ gilt. Interpretiere diese Aussage im vorliegenden Kontext für die Funktion $s$ im Zeitintervall $[0;26,04]$.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$s''(t)=-\frac{7}{75}\cdot t+1,4$

		$s'''(t)=-\frac{7}{75}$

		$s''(t)=0 \Leftrightarrow t=15$

		$s'''(15)=-\frac{7}{75}\neq 0$} %Lösung von Unterpunkt1
\Subitem{Mögliche Interpretation:

		Nach ca. 15 Sekunden erreicht die Läuferin ihre Höchstgeschwindigkeit.

		oder:

		Bis zum Zeitpunkt $t=15$ Sekunden nimmt die Geschwindigkeit der Läuferin zu.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung, wobei der Nachweis, dass bei $t = 15$ eine Wendestelle vorliegt (z. B. durch $s'''(15)\neq 0$), nicht angeführt werden muss. 

Toleranzintervall für $t: [14; 16]$ 

		Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist. } %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine (sinngemäß) korrekte Interpretation.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$\frac{200}{26,04}\approx 7,68$

		Die mittlere Geschwindigkeit beträgt ca. $7,68\,m/s$.} %Lösung von Unterpunkt1
\Subitem{Es gibt mindestens einen Zeitpunkt, für den die Momentangeschwindigkeit der Läuferin gleich der mittleren Geschwindigkeit für die gesamte Laufstrecke ist.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die richtige Lösung, wobei die Einheit nicht angeführt werden muss.

Toleranzintervall: $[7,6; 7,7]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine (sinngemäß) korrekte Interpretation.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

