\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Gib diejenigen Blutgruppen an, die laut der abgebildeten Diagramme sowohl in Österreich als auch in Deutschland häufiger anzutreffen sind als im weltweiten Durchschnitt.} %Unterpunkt1
\Subitem{Jemand argumentiert anhand der gegebenen Diagramme, dass die Blutgruppe B in Deutschland und Österreich zusammen eine relative Häufigkeit von 13\,\% hat.  Entscheide, ob diese Aussage richtig ist, und begründe deine Entscheidung.} %Unterpunkt2

\item Eine in Österreich lebende Person $X$ hat Blutgruppe A-.%Aufgabentext

\Subitem{Gib anhand der in der Einleitung angeführten Daten und Informationen die Wahrscheinlichkeit an, mit der diese Person $X$ als Blutspender/in für eine zufällig ausgewählte, in Österreich lebende Person $Y$ geeignet ist.} %Unterpunkt1
\Subitem{Wie viele von 100 zufällig ausgewählten Österreicherinnen/Österreichern kommen als Blutspender/in für die Person $X$ in Frage? Gib für die Anzahl der potenziellen Blutspender/innen näherungsweise ein um den Erwartungswert symmetrisches Intervall mit 90\,\% Wahrscheinlichkeit an.} %Unterpunkt2

\item In einer österreichischen Gemeinde, in der 1\,800 Einwohner/innen Blut spenden könnten, nahmen 150 Personen an einer freiwilligen Blutspendeaktion teil. Es wird angenommen, dass die Blutspender/innen eine Zufallsstichprobe darstellen. 72 Blutspender/innen hatten Blutgruppe A.%Aufgabentext

\Subitem{Berechne aufgrund dieses Stichprobenergebnisses ein symmetrisches 95-\%-Konfidenzintervall für den tatsächlichen (relativen) Anteil $p$ der Einwohner/innen dieser Gemeinde mit Blutgruppe A, die Blut spenden könnten.} %Unterpunkt1
\Subitem{Die Breite des Konfidenzintervalls wird vom Konfidenzniveau (Sicherheitsniveau) und vom Umfang der Stichprobe bestimmt. Gib an, wie jeweils einer der beiden Parameter geändert werden müsste, um eine Verringerung der Breite des Konfidenzintervalls zu erreichen! Gehe dabei von einem unveränderten (gleichbleibenden) Stichprobenergebnis aus.} %Unterpunkt2

\item Blutgruppenmerkmale werden von den Eltern an ihre Kinder weitervererbt. Dabei sind die  Wahrscheinlichkeiten in der nachstehenden Tabelle angeführt.\leer

\begin{tabular}{|p{3cm}|>{\centering\arraybackslash}p{1,5cm}|>{\centering\arraybackslash}p{1,5cm}|>{\centering\arraybackslash}p{1,5cm}|>{\centering\arraybackslash}p{1,5cm}|}\hline
\multirow{2}{3cm}{Blutgruppe der Eltern}&\multicolumn{4}{|c|}{mögliche Blutgruppe des Kindes}\\ \cline{2-5}
&A&B&AB&0\\ \hline
A und A&$93,75\,\%$&$-$&$-$&$6,25\,\%$\\ \hline
A und B&$18,75\,\%$&$18,75\,\%$&$56,25\,\%$&$6,25\,\%$\\ \hline
A und AB&$50\,\%$&$12,5\,\%$&$37,5\,\%$&$-$\\ \hline
A und 0&$75\,\%$&$-$&$-$&$25\,\%$\\ \hline
B und B&$-$&$93,75\,\%$&$-$&$6,25\,\%$\\ \hline
B und AB&$12,5\,\%$&$50\,\%$&$37,5\,\%$&$-$\\ \hline
B und 0&$-$&$75\,\%$&$-$&$25\,\%$\\ \hline
AB und AB&$25\,\%$&$25\,\%$&$50\,\%$&$-$\\ \hline
AB und 0&$50\,\%$&$50\,\%$&$-$&$-$\\ \hline
0 und 0&$-$&$-$&$-$&$100\,\%$\\ \hline
\end{tabular}

\begin{scriptsize}Datenquelle: https://de.wikipedia.org/wiki/AB0-System [26.11.2014]\end{scriptsize}%Aufgabentext

\Subitem{Eine Frau mit Blutgruppe A und ein Mann mit Blutgruppe 0 haben zwei (gemeinsame) leibliche Kinder.  Berechne die Wahrscheinlichkeit, dass beide Kinder die gleiche Blutgruppe haben.} %Unterpunkt1
\Subitem{Ein Kind aus der Nachbarschaft dieser Familie hat Blutgruppe 0. Gibt es eine Blutgruppe bzw. Blutgruppen, die der leibliche Vater dieses Kindes sicher nicht haben kann? Begründe deine Antwort anhand der gegebenen Daten.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Blutgruppen: A und AB} %Lösung von Unterpunkt1
\Subitem{Die Aussage ist nicht richtig, weil die Anzahl der Einwohner/innen in den beiden genannten Ländern nicht gleich groß ist.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die ausschließliche Angabe der beiden Blutgruppen A und AB.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Angabe, dass die Aussage nicht richtig ist, und eine (sinngemäß) korrekte Begründung dafür.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Die Wahrscheinlichkeit beträgt $48\,\%$.} %Lösung von Unterpunkt1
\Subitem{Mögliche Berechnung:

		$n=100, p=0,15 \Rightarrow \mu=15$

		$2\cdot\Phi(z)-1=0,9 \Rightarrow z=1,645$

		$\mu\pm z\cdot\sigma=15\pm 1,645\cdot\sqrt{100\cdot 0,15\cdot 0,85}\approx 15\pm 6 \Rightarrow [9;21]$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung. Äquivalente Schreibweisen des Ergebnisses (als Bruch oder Dezimalzahl) sind ebenfalls als richtig zu werten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für ein korrektes Intervall.  

	Toleranzintervall für den unteren Wert: $[9; 10]$  

	Toleranzintervall für den oberen Wert: $[20; 21]$  

	Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Berechnung:

	$n=150, h=0,48$

	$2\cdot\Phi(z)-1=0,95 \Rightarrow z=1,96$

	$h\pm z\cdot\sqrt{\frac{h\cdot (1-h)}{n}}=0,48\pm 1,96\cdot\sqrt{\frac{0,48\cdot (1-0,48)}{150}}\approx 0,48\pm 0,08 \Rightarrow [40\,\%;56\,\%]$} %Lösung von Unterpunkt1
\Subitem{Bei gleichem Stichprobenergebnis führen eine größere Stichprobe und/oder ein geringeres Konfidenzniveau zu einer Verringerung der Breite des Konfidenzintervalls.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für ein korrektes Intervall. Äquivalente Schreibweisen des Ergebnisses (als Bruch oder Dezimalzahl) sind ebenfalls als richtig zu werten. 

	Toleranzintervall für den unteren Wert: $[39\,\%; 43\,\%]$  

	Toleranzintervall für den oberen Wert: $[53\,\%; 57\,\%]$  

	Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine (sinngemäß) korrekte Angabe der entsprechenden Änderungen beider  Parameter.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$0,75^2+0,25^2=0,625$

	Die Wahrscheinlichkeit, dass beide Kinder die gleiche Blutgruppe haben, beträgt 62,5\,\%.} %Lösung von Unterpunkt1
\Subitem{Der Vater kann nicht Blutgruppe AB haben, denn sobald ein Elternteil Blutgruppe AB hat, hat das Kind laut Tabelle nie Blutgruppe 0.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung. Äquivalente Schreibweisen des Ergebnisses (als Bruch oder in Prozenten) sind ebenfalls als richtig zu werten. Toleranzintervall: $[0,62; 0,63]$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Antwort und eine (sinngemäß) korrekte Begründung, warum (nur) Blutgruppe AB auszuschließen ist.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

134.content:
Der Innenraum eines 20 cm hohen Gefäßes hat in jeder Höhe $h$ eine rechteckige, horizontale Querschnittsfläche. Ihre Länge beträgt am Boden 10 cm und nimmt dann mit der Höhe linear bis auf 16 cm zu, ihre Breite beträgt in jeder Höhe 12 cm.

				\begin{center}
					\resizebox{0.6\linewidth}{!}{\includegraphics{../_database/Bilder/Bild48-1.eps}}
				\end{center}%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Gib eine Formel für die Länge $a(h)$ der rechteckigen Querschnittsfläche in der Höhe $h$ an.} %Unterpunkt1
\Subitem{In das Gefäß wird Flüssigkeit gefüllt.

	Gib an, was der Ausdruck $12\cdot\displaystyle\int^{15}_0{a(h)}$d$h$ in diesem Zusammenhang bedeutet.} %Unterpunkt2

\item Das leere Gefäß wird bis zum Rand mit Flüssigkeit gefüllt.

Nach $t$ Sekunden befindet sich die Wassermenge $q(t)$ (in ml) im Gefäß. Die Füllung dauert 39 Sekunden. Für $t\in[0;39]$ gilt: $q'(t)=80$.%Aufgabentext

\Subitem{Interpretiere $q'(t)=80$ im gegebenen Zusammenhang.} %Unterpunkt1
\Subitem{Ermittle $\frac{q(t_2)-q(t_1)}{t_2-t_1}$ für beliebige $t_1,t_2$ mit $t_1<t_2$ aus dem gegebenen Zeitintervall.} %Unterpunkt2

\item Das Fassungsvermögen des Gefäßes (in ml) bis zur Höhe $x$ kann durch das Integral $\displaystyle\int^x_0{(3,6\cdot h+120)}\dx[h]$ dargestellt werden.%Aufgabentext

\Subitem{Ermittle, bei welcher Höhe $x$ das Wasser im Gefäß steht, wenn man 2,5 Liter Wasser in das Gefäß gießt.} %Unterpunkt1
\Subitem{Interpretiere den im Integral vorkommenden Wert $3,6$ im gegebenen Kontext} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$a(h)=k\cdot h+d$

	$a(0)=d=10$

	$a(20)=20\cdot k+10=16 \Rightarrow k=0,3$

	$a(h)=0,3\cdot h+10$} %Lösung von Unterpunkt1
\Subitem{Das Integral gibt das Volumen der enthaltenen Flüssigkeit (in ml) an, wenn das Gefäß bis 5 cm unter dem Rand (bzw. bis zu einer Höhe von 15 cm) gefüllt ist.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für eine korrekte Formel. Äquivalente Formeln sind ebenfalls als richtig zu werten. Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine (sinngemäß) korrekte Interpretation.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Die momentane Änderungsrate der Wassermenge beträgt im gesamten Zeitintervall 80 Milliliter pro Sekunde.} %Lösung von Unterpunkt1
\Subitem{$\dfrac{q(t_2)-q(t_1)}{t_2-t_1}=80$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine (sinngemäß) korrekte Interpretation.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$2500=\int^x_0{(3,6\cdot h+120)}$d$h=1,8x^2+120x$

	$1,8x^2+120x-2500=0$

	$x_1\approx 16,7, (x_2<0)$

	Das Wasser steht ca. 16,7 cm hoch.} %Lösung von Unterpunkt1
\Subitem{3,6 gibt diejenige Fläche in cm$^2$ an, um die die Querschnittsfläche mit jedem zusätzlichen cm Höhe zunimmt. 

	oder: 

	3,6 ist die Steigung der Funktion, die den Inhalt der Querschnittsfläche in der Höhe $h$ angibt.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung, wobei weder die negative Lösung der quadratischen Gleichung noch die Einheit cm angeführt werden müssen.

		Toleranzintervall: $[16,5; 17]$  

		Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine (sinngemäß) korrekte Interpretation.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

