\rput[bl](3.9,7.58){\qqwuqq{$\alpha$}}
\end{pspicture*}}
\end{center}
\begin{scriptsize} Bildquelle: http://www.overclockers.at/games\_forum/euer-erstes-computerspiel\_237146/page\_2 [15.10.2015]. \end{scriptsize}

%Aufgabentext

\begin{aufgabenstellung}
\item In einer konkreten Spielsituation hat der Ball beim Aufprall auf den oberen Spielfeldrand einen Geschwindigkeitsvektor von $\vec{v}=\binom{4}{7}$ Pixeln pro Bildaufbau.%Aufgabentext

\Subitem{Gib denjenigen Winkel $\alpha$ an, unter dem der Ball auf den Spielfeldrand trifft.\vspace{0,3cm}

	$\alpha$= \rule{5cm}{0.3pt}} %Unterpunkt1

	Die Komponenten des Geschwindigkeitsvektors sind immer ganzzahlig. Nehmen Sie an, dass die Summe der Beträge der Komponenten nicht größer als 20 sein darf.

\Subitem{Der Ball wird am oberen Spielfeldrand unter dem Winkel $\beta$ reflektiert. Welchen kleinstmöglichen Wert $\beta_\text{min}$ kann unter diesen Voraussetzungen der Winkel $\beta$ annehmen? Gib $\beta_\text{min}$ an.\vspace{0,3cm}

	$\beta_\text{min}$= \rule{5cm}{0.3pt}} %Unterpunkt2

\item In einem anderen Spielverlauf befindet sich der Ball im Punkt $(401|301)$ und sein Geschwindigkeitsvektor ist dabei $\vec{v}=\binom{2}{-3}$ Pixel pro Bildaufbau.%Aufgabentext

\Subitem{Gib an, wie viele \textit{Sekunden} es dauert, bis der Ball am unteren Spielfeldrand reflektiert wird.} %Unterpunkt1

Nach dieser Reflexion bewegt sich der Ball entlang einer Geraden bis zum nächsten Auftreffen auf den Schläger oder den Spielfeldrand.

\Subitem{Gib eine Parameterdarstellung dieser Geraden an.} %Unterpunkt2

\item Zwei Kinder, Nicola und Florian, spielen über einen längeren Zeitraum oft gegeneinander \textit{Pong}. Von 45 Spielen gewinnt Nicola 31-mal, Florian gewinnt 14-mal.%Aufgabentext

\Subitem{Gib auf Basis dieser Information ein symmetrisches $95-\%-$Konfidenzintervall für Nicolas Gewinnwahrscheinlichkeit an.} %Unterpunkt1
\Subitem{Erkläre, wieso es nicht sinnvoll ist, ein 100-\%-Konfidenzintervall zu bestimmen.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$\tan(\alpha)=\frac{7}{4}=1,74$

$\alpha\approx 60,26^\circ$} %Lösung von Unterpunkt1
\Subitem{Unter diesen Bedingungen lautet der Geschwindigkeitsvektor $\vec{v}= \binom{\pm\,19}{\pm\,1}$ Pixel pro Bildaufbau. Für den Winkel $\beta_\text{min}$ gibt das in jedem Fall:

 $\tan(\beta_\text{min})=\frac{1}{19}$

 $\beta_\text{min}\approx 3,01^\circ$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die richtige Lösung, wobei die Einheit "`Grad"' nicht angegeben sein muss. Eine korrekte Angabe der Lösung in einer anderen Einheit ist ebenfalls als richtig zu werten. 

		Toleranzintervall: $[6011^\circ; 60,3^\circ]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung, wobei die Einheit "`Grad"' nicht angegeben sein muss. Eine korrekte Angabe der Lösung in einer anderen Einheit ist ebenfalls als richtig zu werten. 

		Toleranzintervall: $[3^\circ; 3,02^\circ]$} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$301-3n=1 \Rightarrow n=100$

	$100\cdot 0,02=2$

	Es dauert zwei Sekunden, bis der Ball am unteren Spielfeldrand reflektiert wird.} %Lösung von Unterpunkt1
\Subitem{$g: X=\binom{601}{1}+s\cdot\binom{2}{3}$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung. 

	Toleranzintervall: $[2\,\text{s}; 2,02\,\text{s}]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine korrekte Parameterdarstellung bzw. Gleichung der Geraden. Äquivalente Parameterdarstellungen bzw. Gleichungen sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$n=45, h=\frac{31}{45}$

$\frac{31}{45}\,\pm\,1,96\cdot\sqrt{\frac{\frac{31}{45}\cdot\frac{14}{45}}{45}}\approx 0,689\,\pm\,0,135 \Rightarrow [0,554;0,824]$} %Lösung von Unterpunkt1
\Subitem{Mögliche Erklärungen:

Es ist nicht sinnvoll, ein 100-\%-Konfidenzintervall zu bilden, da die Intervallgrenzen dann 0\,\% bis 100\.\% wären, man hätte also keinen Informationsgewinn. 

 oder:  

 Ein 100-\%-Konfidenzintervall erstreckt sich über den gesamten Definitionsbereich.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für ein korrektes Intervall. Andere Schreibweisen des Ergebnisses (als Bruch oder in Prozent) sind ebenfalls als richtig zu werten. 

	Toleranzintervall für den unteren Wert: $[0,54; 0,56]$ 

	Toleranzintervall für den oberen Wert: $[0,81; 0,83]$ 

	Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist. } %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine (sinngemäß) korrekte Erklärung.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

