159.content:
Betrachtet werden quadratische Funktionen der Form $x\mapsto a\cdot x^2+b\cdot x+c$ mit $a,b,c\in\mathbb{R}$ und $a\neq 0$. Die Wahl der Koeffizienten $a,b$ und $c$ beeinflusst verschiedene Eigenschaften wie Monotonie, Monotoniewechsel, Achsensymmetrie und Schnittpunkte mit den Achsen.%Aufgabentext

\begin{aufgabenstellung}
\item Der Graph einer quadratischen Funktion $f$ ist symmetrisch zur senkrechten Achse und schneidet die $x$-Achse an den Stellen $x_1$ und $x_2$ mit $x_1<x_2$. Es gilt: $\displaystyle\int^{x_2}_{x_1}{f(x)}\dx=d$ mit $d\in\mathbb{R}^+$.%Aufgabentext

\Subitem{Veranschauliche den Wert $d$ mithilfe eines passenden Graphen einer solchen Funktion $f$ im nachstehenden Koordinatensystems!\vspace{0,3cm}

	\begin{center}
	\newrgbcolor{zzttqq}{0.6 0.2 0.}
\psset{xunit=0.7cm,yunit=0.7cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=4pt 0,linewidth=0.8pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-4.526147391499742,-4.633854256009012)(4.748685856341189,4.827834606715162)
\multips(0,-4)(0,1.0){10}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(-4.526147391499742,0)(4.748685856341189,0)}
\multips(-4,0)(1.0,0){10}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,-4.633854256009012)(0,4.827834606715162)}
\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,labels=none,Dx=1.,Dy=1.,ticksize=-2pt 0,subticks=0]{->}(0,0)(-4.526147391499742,-4.633854256009012)(4.748685856341189,4.827834606715162)[$x$,140] [$f(x)$,-40]
\antwort{\rput[tl](0.28113797322367096,1.481420412897097){d}
\pscustom[linewidth=0.8pt,linecolor=zzttqq,hatchcolor=zzttqq,fillstyle=hlines,hatchangle=45.0,hatchsep=0.16]{\psplot{-3.}{3.}{-0.33*x^2+3}\lineto(3.,0)\lineto(-3.,0)\closepath}
\psplot[linewidth=1.2pt,plotpoints=200]{-4.526147391499742}{4.748685856341189}{-0.33*x^2+3}
\rput[tl](-2.9,-0.1){$x_1$}
\rput[tl](2.6,-0.1){$x_2$}
\rput[tl](0.28113797322367096,1.481420412897097){d}
\rput[bl](-4.2,-2.){$f$}}
\end{pspicture*}
	\end{center}} %Unterpunkt1

\setcounter{subitemcounter}{1}
\Subitem{Gib für jeden der Koeffizienten $a,b$ und $c$ dieser Funktion $f$ an, ob er positiv, negativ oder genau null sein muss.} %Unterpunkt2

\item Der Graph einer quadratischen Funktion $g$ hat einen Tiefpunkt und an den Stellen $x_1=0$ und $x_2>0$ Schnittpunkte mit der $x$-Achse. Die Nullstelle $x_2$ lässt sich mithilfe der Koeffizienten der Funktion $g$ berechnen.%Aufgabentext

\Subitem{Stelle eine entsprechende Formel auf.} %Unterpunkt1

Der Graph der Funktion $g$ begrenzt mit der $x$-Achse eine endliche Fläche.

\Subitem{Gib ein bestimmtes Integral an, mit dessen Hilfe der Inhalt dieser endlichen Fläche berechnet werden kann.} %Unterpunkt2

\item Für eine Stelle $k$ $(k\in\mathbb{R})$ des Graphen einer quadratischen Funktion $h$ gelten die Bedingungen $h(k)=0$ und $h'(k)=0$.%Aufgabentext

\Subitem{Skizziere einen möglichen Verlauf des Graphen von $h$ und kennzeichne die Stelle $k$ im nachstehenden Koordinatensystem.

	\begin{center}
\psset{xunit=0.7cm,yunit=0.7cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=4pt 0,linewidth=0.8pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-4.526147391499742,-4.633854256009012)(4.748685856341189,4.827834606715162)
\multips(0,-4)(0,1.0){10}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(-4.526147391499742,0)(4.748685856341189,0)}
\multips(-4,0)(1.0,0){10}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,-4.633854256009012)(0,4.827834606715162)}
\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,labels=none,Dx=1.,Dy=1.,ticksize=-2pt 0,subticks=2]{->}(0,0)(-4.526147391499742,-4.633854256009012)(4.748685856341189,4.827834606715162)[$x$,140] [$h(x)$,-40]
\antwort{\psplot[linewidth=1.2pt,plotpoints=200]{-4.526147391499742}{4.748685856341189}{x^2-4*x+4}
\psdots[dotsize=5pt 0,dotstyle=*](2.,0.)
\rput[tl](2,-0.1){$k$}
\rput[bl](3.5,1.7){$h$}}
\end{pspicture*}
	\end{center}} %Unterpunkt1
	\setcounter{subitemcounter}{1}
\Subitem{Zeige rechnerisch, dass eine Funktion $h$ mit der Funktionsgleichung \mbox{$h(x)=x^2-2\cdot k\cdot x+k^2$} die Bedingungen $h(k)=0$ und $h'(k)=0$ erfüllt.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Grafik: Lösung siehe oben.} %Lösung von Unterpunkt1
\Subitem{$a<0, b=0$ und $c>0$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine korrekte Veranschaulichung des Wertes $d$, wobei der Graph von $f$ klar erkennbar die Form einer achsensymmetrischen und nach unten offenen Parabel haben muss.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Angabe der richtigen Bedingungen für die Koeffizienten $a, b$ und $c$.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$g(x)=a\cdot x^2+b\cdot x$} %Lösung von Unterpunkt1
\Subitem{$a\cdot x^2+b\cdot x=0 \Rightarrow (x_1=0), x_2=-\frac{b}{a}$ mit $a>0$ und $b<0$

Mögliche Berechnung des gesuchten Flächeninhalts:

$\displaystyle\int^0_{-\frac{b}{a}}{g(x)}\dx$

oder:

$-\displaystyle\int^{x_2}_0{g(x)}\dx$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine korrekte Formel, wobei die Bedingungen  $a>0$  und  $b<0$  nicht angeführt werden müssen. Äquivalente Formeln sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für ein korrektes bestimmtes Integral. Äquivalente Ausdrücke sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Grafik: Lösung siehe oben.} %Lösung von Unterpunkt1
\Subitem{$h(k)=k^2-2\cdot k^2+k^2=0 \Rightarrow h(k)=0$

$h'(x)=2\cdot x-2\cdot k$

$h'(k)=2\cdot k-2\cdot k=0 \Rightarrow h'(k)=0$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

