\psaxes[comma,labelFontSize=\scriptstyle,xAxis=true,yAxis=true,Dx=0.25,Dy=250.,ticksize=-2pt 0,subticks=0]{->}(0,0)(0.,0.)(3.225304946195222,1170.685426243125)
\psplot[linewidth=1.2pt,plotpoints=200]{0}{2.56}{1350/(x+0.36)-460}
\psplot[linewidth=1.2pt,plotpoints=200]{0}{2.57}{(1350/(x+0.36)-460)*x}
\rput[tl](0.45,976.870987886439){F}
\rput[tl](0.13597591920870677,218.22590060455406){P}
\begin{scriptsize}
\rput[tl](2.75,50){$v$ in m/s}
\rput[tl](0.05,1100){$F(v)$ in N}
\rput[tl](0.05,1050){$P(v)$ in W}
\end{scriptsize}
\antwort{\psline[linewidth=0.8pt](0.7,-235.85364068825302)(0.7,1170.685426243125)
\psline[linewidth=0.8pt](0.845346307198817,569.509433962264)(-0.11167409790026661,569.509433962264)
\psdots[dotsize=6pt 0,dotstyle=*](0.7,0.)}
\end{pspicture*}
	\end{center}%Aufgabentext

\Subitem{Ermittle mithilfe der Grafik näherungsweise den Wert derjenigen Kraft (in N), die zu einer maximalen Leistung dieses Muskels führt.} %Unterpunkt1
\Subitem{Ermittle mithilfe der Grafik näherungsweise den Wert der Geschwindigkeit $v_1$ der Muskelkontraktion, für den $P'(v_1)=0$ gilt.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$F(0)\approx 2\,900$\,N

$F(0)$ gibt den Wert derjenigen Kraft an, die der Muskel bei einer Kontraktionsgeschwindigkeit von  $v=0$  aufbringt.} %Lösung von Unterpunkt1
\Subitem{Zwischen $F$ und $v$ wird keine indirekte Proportionalität beschrieben.

Mögliche Begründung:

Eine Verdoppelung der Kontraktionsgeschwindigkeit $v$ führt nicht zu einer Halbierung der Muskelkraft $F$.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung und eine (sinngemäß) korrekte Deutung, wobei die Einheit "`Newton"' nicht angeführt sein muss. 

		Toleranzintervall: $[2\,750\,\text{N}; 3\,000\,\text{N}]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Angabe, dass keine indirekte Proportionalität beschrieben wird, und eine korrekte Begründung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Bei ungefähr $800\,$N erreicht der Musekl seine maximale Leistung.} %Lösung von Unterpunkt1
\Subitem{$v_1\approx 0,7\,$m/s} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die richtige Lösung, wobei die Einheit "`Newton"' nicht angeführt sein muss.  

	Toleranzintervall: $[650\,\text{N}; 950\,\text{N}]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung, wobei die Einheit "`m/s"' nicht angeführt sein muss. 

	Toleranzintervall: $[0,6\,\text{m/s}; 0,9\,\text{m/s}]$} %Lösungschlüssel von Unterpunkt2

\end{loesung}

