\rput[tl](0.45,1413.999044666503){$F$}
\end{scriptsize}
\psplot[linewidth=1.2pt,plotpoints=200]{0}{2.6}{1500/(x+0.45)-500}
\end{pspicture*}
\end{center}%Aufgabentext

\begin{aufgabenstellung}
