\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,Dx=0.25,Dy=250.,ticksize=-2pt 0,subticks=0]{->}(0,0)(0.,0.)(3.225304946195222,1170.685426243125)
