\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Ermittle die Funktionsgleichung von $f_1$, wobei die Variable $t$ die nach dem Jahr 1990 vergangene Zeit in Jahren angibt.} %Unterpunkt1
\Subitem{Berechne, wann gemäß Szenario 1 der Tropenwaldbestand auf weniger als 100 Millionen Hektar gesunken sein wird.} %Unterpunkt2

\item 

\Subitem{Gib die Gleichung derjenigen Funktion $f_2$ an, die den Bestand $t$ Jahre nach 1990 unter der Annahme einer konstanten Abnahme von 17 Millionen Hektar pro Jahr modelliert.}
\Subitem{Gib an, in welchem Jahr entsprechend diesem Modell der Tropenwald von der Erdoberfläche verschwinden würde, und zeichne den Graphen dieser Funktion in der Abbildung 1 ein.}

\item Geh in den nachstehenden Aufgabenstellungen auf Meadows' Annahme einer exponentiell zunehmenden Abholzungsrate ein und beantworte mithilfe der gegebenen Abbildungen.

\Subitem{Gib näherungsweise denjenigen Zeitpunkt $t_1$ an, zu dem die momentane Abholzungsrate auf ca. 24 Millionen Hektar pro Jahr angewachsen ist.}
\Subitem{Bestimme näherungsweise den Wert des Integrals $\displaystyle\int^{t_1}_0{f_3'(t)}\dx[t]$ durch Ablesen aus den Abbildungen und gib seine Bedeutung im Zusammenhang mit der Abholzung der tropischen Wälder an.}

\item Ein internationales Forscherteam um den Geografen Matthew Hansen von der University of Maryland hat mithilfe von Satellitenfotos die Veränderung des Baumbestands des Tropenwaldes von 2000 bis 2012 ermittelt. Dabei wurde festgestellt, dass in jedem Jahr durchschnittlich um $a$ Millionen Hektar $(a>0)$ mehr abgeholzt wurden als im Jahr davor.

\Subitem{Begründe, warum das von Meadows entworfene Szenario 3 am ehesten den Beobachtungen von Matthew Hansen entspricht.}
\Subitem{Das Team von Hansen gibt für $a$ den Wert 0,2101 Millionen Hektar pro Jahr an. Gib an, ob die im Modell von Meadows für den Zeitraum 2000 bis 2012 vorhergesagten Änderungsraten der Abholzungsrate größer oder kleiner als die von Hansen beobachteten sind, und begründe deine Entscheidung.}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$f_1(t)=800\cdot 0,979^t$} %Lösung von Unterpunkt1
\Subitem{$800\cdot 0,979^t<100 \Rightarrow t>97,977$...

Nach Szenario 1 wird der Tropenwaldbestand nach ca. 98 Jahren auf weniger als 100 Millionen Hektar gesunken sein.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für eine korrekte Funktionsgleichung. Äquivalente Funktionsgleichungen sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung, wobei die Einheit "`Jahre"' nicht angegeben sein muss. 

		Toleranzintervall: $[93\,\text{Jahre}; 104\,\text{Jahre}]$

		Die Aufgabe ist auch dann als richtig gelöst zu werten, wenn bei korrektem Ansatz das Ergebnis aufgrund eines Rechenfehlers nicht richtig ist.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$f_2(t)=-17\cdot t+800$ $(\text{bzw. }f_2(t)=-17\,000\,000\cdot t+800\,000\,000)$} %Lösung von Unterpunkt1
\Subitem{Entsprechend diesem Modell würde der Tropenwald im Laufe des Jahres 2037 verschwinden.

Grafik: Lösung siehe oben.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine korrekte Funktionsgleichung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Angabe einer korrekten Jahreszahl sowie eines korrekten Graphen, wobei dieser als Gerade erkennbar sein muss, die durch $(0|800)$ verläuft und deren Schnittpunkt mit der Zeitachse im Toleranzintervall $[45; 50]$ liegt. 

	Toleranzintervall für das gesuchte Jahr: $[2035; 2040]$} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$t_1\approx 15$ (also im Jahr 2005)} %Lösung von Unterpunkt1
\Subitem{$\displaystyle\int^{t_1}_0{f_3'(t)}\dx[t]\approx -300$ $(\text{bzw. }-300\,000\,000)$

	In den 15 Jahren nach 1990 wurden ca. 300 Millionen Hektar Tropenwald gerodet.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung. 

	Toleranzintervall: $[14; 16]$ bzw. $[2004; 2006]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung, wobei auch der Betrag der Lösung als richtig zu werten ist, sowie für eine (sinngemäß) korrekte Interpretation. 

	Toleranzintervall: $[-350; -250]$ (bzw. $[-350 000 000; -250 000 000]$)} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Eine Übereinstimmung ist am ehesten mit dem Szenario 3 festzustellen, da dieses Modell ebenso von einer jährlich zunehmenden Abholzungsrate ausgeht.

Das Modell von Meadows sagt für diesen Zeitraum eine deutlich größere Änderung der Abholzungsrate voraus.
} %Lösung von Unterpunkt1
\Subitem{Mögliche Begründung: Der Betrag der Steigung der Funktion $f_3'$ ist im Zeitraum 2000 bis 2012 deutlich größer als 0,2101.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine (sinngemäß) korrekte Begründung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine richtige Entscheidung und eine korrekte Begründung.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

