Hängt man ein Seil (oder beispielsweise eine Kette) an zwei Punkten auf, so kann der Verlauf des Seils unter bestimmten Bedingungen durch eine Funktion der Form $x\mapsto \frac{a}{2}\cdot\left(e^\frac{x}{a}+e^{-\frac{x}{a}}\right)$ mit $a\in\mathbb{R}^+$ modelliert werden.

Der Wert der Konstanten $a$ hängt dabei von der Seillänge und vom Abstand der beiden Aufhängepunkte ab.

Der vertikale Abstand zwischen dem tiefsten Punkt des Seils und seinen Aufhängepunkten wird als Durchhang bezeichnet.

Ein bestimmtes Seil kann modellhaft durch eine Funktion $f$ der obigen Form mit $a=4$ beschrieben werden ($x$ und $f(x)$ in Metern). Die beiden Aufhängepunkte $P_1$ und $P_2$ befinden sich in gleicher Höhe und ihr Abstand beträgt $d=6$\,cm.%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Gib eine Gleichung an, mit der die Stelle mit dem maximalen Durchhang des durch $f$ beschriebenen Seils berechnet werden kann, und ermittle diese Stelle.} %Unterpunkt1
\Subitem{Gib eine Funktionsgleichung $f_1$ an, mit der ein Seil modelliert werden kann, welches an jeweils 1\,m tieferen Aufhängepunkten montiert ist und denselben Durchhang wie das durch $f$ beschriebene Seil aufweist.} %Unterpunkt2

\item %Aufgabentext

\Subitem{Gib eine Gleichung an, mit der der Durchhang $\delta_1$, der die Abhängigkeit des Durchhangs von der Länge des Seils zwischen den Aufhängepunkten $P_1$ und $P_2$ beschreibt.} %Unterpunkt1
\Subitem{Gib mithilfe der unten dargestellten Abbildung die Länge des in der Einleitung beschriebenen Seils an! Ermittle weiters, um wie viele Meter der Durchhang zunimmt, wenn das Seil durch ein zwei Meter längeres Seil (gleicher Beschaffenheit) ersetzt wird, das an denselben Aufhängepunkten montiert ist.

\begin{center}
	\resizebox{0.9\linewidth}{!}{\includegraphics{../_database/Bilder/Bild77-1.eps}}
\end{center}} %Unterpunkt2

\item Der Graph der Funktion $f$ kann durch den Graphen einer quadratischen Funktion $g$ mit $g(x)=b\cdot x^2+c$ mit $b,c\in\mathbb{R}^+$ angenähert werden. Der Graph von $g$ verläuft durch die Aufhängepunkte $P_1$ und $P_2$ und den Tiefpunkt des Graphen von $f$.%Aufgabentext

\Subitem{Gib alle Gleichungen an, die für die Berechnung von $b$ und $c$ notwendig sind, und ermittle die Werte dieser Parameter.} %Unterpunkt1
\Subitem{Gib eine Gleichung an, mit der der größte vertikale Abstand von $f$ und $g$ zwischen den beiden Aufhängepunkten berechnet werden kann.} %Unterpunkt2

\item Der Graph der Funktion $f$ kann auch durch den Graphen einer Polynomfunktion $f$ vierten Grades angenähert werden. Für den Graphen von $h$ gelten folgende Bedingungen: er verläuft durch die Aufhängepunkte $P_1$ und $P_2$ und den Tiefpunkt des Graphen von $f$ und hat in den beiden Aufhängepunkten dieselbe Steigung wie der Graph von $f$.%Aufgabentext

\Subitem{Drücke \underline{alle} gegebenen Bedingungen mithilfe von Gleichungen aus.} %Unterpunkt1
\Subitem{Ermittle anhand dieser Gleichungen eine Funktionsgleichung von $h$.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$f'(x)=\frac{1}{2}\cdot\left(e^{\frac{x}{4}}+e^{-\frac{x}{4}}\right)=0 \Rightarrow x=0$} %Lösung von Unterpunkt1
\Subitem{$f_1(x)=f(x)-1=\frac{4}{2}\cdot\left(e^{\frac{x}{4}}+e^{-\frac{x}{4}}\right)-1$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die Stelle mit dem maximalen Durchhang.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für entsprechende Funktionsgleichung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$\delta=f(3)-f(0)$

	$\delta=1,2$\,m} %Lösung von Unterpunkt1
\Subitem{Die Seillänge beträgt ca. 6,6\,m.

	$\delta_1(8,6)\approx 2,8 \Rightarrow$ Der Durchhang nimmt um ca. 1,6\,m zu.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Gleichung und den richtigen Wert.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Seillänge und der Zunahme des Durchhangs.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$g(0)=4=c$

$g(3)=f(3)\approx 5,18=9\cdot b+4 \Rightarrow b\approx 0,13$} %Lösung von Unterpunkt1
\Subitem{größter vertikaler Abstand:

$(g(x)-f(x))'=0$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtigen Parameter.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Gleichung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$h(-3)=f(-3)$

$h(0)=f(0)$

$h(3)=f(3)$

$h'(-3)=f'(-3)$

$h'(3)=f'(3)$} %Lösung von Unterpunkt1
\Subitem{$h(x)\approx 0,0007\cdot x^4+0,125\cdot x^2+4$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für ALLE fünf Gleichungen.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Funktionsgleichung von $h$.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

