Gegeben ist eine quadratische Funktion $f$ mit $f(x)=a\cdot x^2+b\cdot x+c$ mit den Koeffizienten $a,b,c\in\mathbb{R}$.%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Bestimme die Koordinaten desjenigen Punktes $P$ des Graphen einer solchen Funktion $f$, in dem der Anstieg der Tangente an den Graphen der Funktion $f$ den Wert $b$ hat, und gib weiter eine (allgemeine) Gleichung dieser Tangente $f$ an.} %Unterpunkt1
\Subitem{Der Graph einer solchen Funktion $f$ verläuft durch den Punkt $A=(-1\mid 20)$ und hat im Punkt $P$ eine Tangente $t$ mit $t(x)=9\cdot x+4$. Gib für diese Funktion $f$ die Werte von $a,b$ und $c$ an.} %Unterpunkt2

\item %Aufgabentext

\Subitem{Gib $a$ in Abhängigkeit von $b$ und $c$ so an, dass die Funktion $f$ genau eine Nullstelle hat.} %Unterpunkt1
\Subitem{Skizziere im nachstehenden Koordinatensystem einen möglichen Graphen einer solchen Funktion $f$ mit genau einer Nullstelle und $a>0, b>0, c>0$.\vspace{0,3cm}

\begin{center}
\psset{xunit=0.8cm,yunit=0.8cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=0.8pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-5.9,-5.22)(5.76,5.86)
\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,labels=none,Dx=1.,Dy=1.,ticksize=0pt 0,subticks=2]{->}(0,0)(-5.9,-5.22)(5.76,5.86)[$x$,140] [$f(x)$,-40]
\antwort{\psplot[linewidth=1.pt,plotpoints=200]{-5.900000000000002}{5.7600000000000025}{(x+2.0)^(2.0)}
\rput[tl](-3.66,3.74){$f$}}
\end{pspicture*}
	\end{center}} %Unterpunkt2

\item %Aufgabentext

\Subitem{Gib für $a=16$ und $c=9$ sowohl die Stelle des lokalen Extremums der Funktion $f$ als auch zu den zugehörigen Funktionswert in Abhängigkeit von $b$ an.} %Unterpunkt1
\Subitem{Zeig, dass dieser Extrempunkt unabhängig von der Wahl von $b$ auf dem Graphen der Funktion $g$ mit $g(x)=9-16\cdot x^2$ liegt.} %Unterpunkt2



\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Vorgehensweise:

	$f'(x)=2\cdot a\cdot x+b$

	$f'(0)=b$, $x_P=0$, $f(x_P)=x$ $\Rightarrow$ $P=(0\mid c)$

	Steigung der Tangente: $b$, Abschnitt auf der senkrechten Achse: $c$

	$\Rightarrow t(x)=b\cdot x+c$} %Lösung von Unterpunkt1
\Subitem{$b=9$ und $c=4$, $f(-1)=a-9+4=20 \Rightarrow a=25$

	$\Rightarrow a=25, b=9, c=4$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die Angabe der richtigen Koordinaten von $P$ und einer korrekten Gleichung von $t$. Äquivalente Gleichungen sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Angabe der richtigen Werte von $a,b$ und $c$.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Vorgehensweise:

	$b^2-4\cdot a\cdot c=0$ $\Rightarrow$ $a=\frac{b^2}{4\cdot c}$} %Lösung von Unterpunkt1
\Subitem{Mögliche Skizze: siehe oben} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine korrekte Skizze, wobei der Scheitel erkennbar auf der negativen x-Achse liegen und die Parabel nach oben geöffnet sein muss.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$f(x)=16\cdot x^2+b\cdot x+9$, $f'(x)=32\cdot x+b=0$

	$\Rightarrow$ Stelle des loaklen Extremumgs: $x_E=-\frac{b}{32}$

	Funktionswert an der Stelle $x_E:f\left(-\frac{b}{32}\right)=9-\frac{b^2}{64}$} %Lösung von Unterpunkt1
\Subitem{$g\left(-\frac{b}{32}\right)=9-16\cdot\frac{b^2}{32^2}=9-\frac{b^2}{64}$, dieser Ausdruck stimmt mit dem Funktionswert an der Stelle des lokalen Extremums der Funktion $f$ überein.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die Angabe der beiden korrekten Werte.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für einen korrekten Nachweis. Andere korrekte Nachweise sind ebenfalls als richtig zu werten.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

175.content_translation:
Let $f$ be a quadratic function where $f(x)=a\cdot x^2+b\cdot x+c$ with coefficients $a,b,c\in\mathbb{R}$.%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Determine the coordinates of the point $P$ on the graph of one such function $f$ at which the gradient of the tangent to the graph of the function $f$ has the value $b$ and, furthermore, write down a general equation of this tangent $t$.} %Unterpunkt1
\Subitem{The graph of one such function $f$ goes through the point $A=(-1, 20)$ and has a tangent $t$ where $t(x)=9\cdot x+4$ at point $P$. For this function $f$, write down the values of $a$, $b$ and $c$.} %Unterpunkt2

\item %Aufgabentext

\Subitem{Write down an expression that gives $a$ in terms of $b$ and $c$ such that the function $f$ has exactly one zero.} %Unterpunkt1
\Subitem{In the coordinate system provided below, sketch a possible graph of one such function $f$ with exactly one zero and $a>0, b>0, c>0$.\vspace{0,3cm}

\begin{center}
\psset{xunit=0.8cm,yunit=0.8cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=0.8pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-5.9,-5.22)(5.76,5.86)
\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,labels=none,Dx=1.,Dy=1.,ticksize=0pt 0,subticks=2]{->}(0,0)(-5.9,-5.22)(5.76,5.86)[$x$,140] [$f(x)$,-40]
\antwort{\psplot[linewidth=1.pt,plotpoints=200]{-5.900000000000002}{5.7600000000000025}{(x+2.0)^(2.0)}
\rput[tl](-3.66,3.74){$f$}}
\end{pspicture*}
	\end{center}} %Unterpunkt2

\item %Aufgabentext

\Subitem{For $a=16$ and $c=9$, write down both the position of the local maximum or minimum of the function $f$ as well as the corresponding value of the function at this point in terms of $b$.} %Unterpunkt1
\Subitem{Show that this maximum or minimum lies on the graph of the function $g$ where $g(x)=9-16\cdot x^2$ regardless of the value chosen for $b$.} %Unterpunkt2



\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Vorgehensweise:

	$f'(x)=2\cdot a\cdot x+b$

	$f'(0)=b$, $x_P=0$, $f(x_P)=x$ $\Rightarrow$ $P=(0\mid c)$

	Steigung der Tangente: $b$, Abschnitt auf der senkrechten Achse: $c$

	$\Rightarrow t(x)=b\cdot x+c$} %Lösung von Unterpunkt1
\Subitem{$b=9$ und $c=4$, $f(-1)=a-9+4=20 \Rightarrow a=25$

	$\Rightarrow a=25, b=9, c=4$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die Angabe der richtigen Koordinaten von $P$ und einer korrekten Gleichung von $t$. Äquivalente Gleichungen sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Angabe der richtigen Werte von $a,b$ und $c$.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Vorgehensweise:

	$b^2-4\cdot a\cdot c=0$ $\Rightarrow$ $a=\frac{b^2}{4\cdot c}$} %Lösung von Unterpunkt1
\Subitem{Mögliche Skizze: siehe oben} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine korrekte Skizze, wobei der Scheitel erkennbar auf der negativen x-Achse liegen und die Parabel nach oben geöffnet sein muss.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$f(x)=16\cdot x^2+b\cdot x+9$, $f'(x)=32\cdot x+b=0$

	$\Rightarrow$ Stelle des loaklen Extremumgs: $x_E=-\frac{b}{32}$

	Funktionswert an der Stelle $x_E:f\left(-\frac{b}{32}\right)=9-\frac{b^2}{64}$} %Lösung von Unterpunkt1
\Subitem{$g\left(-\frac{b}{32}\right)=9-16\cdot\frac{b^2}{32^2}=9-\frac{b^2}{64}$, dieser Ausdruck stimmt mit dem Funktionswert an der Stelle des lokalen Extremums der Funktion $f$ überein.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für die Angabe der beiden korrekten Werte.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für einen korrekten Nachweis. Andere korrekte Nachweise sind ebenfalls als richtig zu werten.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

