179.content_translation:
Let $f$ be a third degree polynomial function with equation $f(x)=a\cdot x^3+b\cdot x$ with coefficients $a,b\in\mathbb{R}\backslash\{0\}$.%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Justify why the function $f$ has exactly three distinct real roots if the coefficients $a$ and $b$ have different signs.} %Unterpunkt1
\Subitem{The gradient of the tangent to the graph of $f$ at the point where $x=0$ is equal to the value of the coefficient $b$. Justify why this statement is true.} %Unterpunkt2

\item %Aufgabentext

\Subitem{Determine the relationship between the coefficients $a$ and $b$ such that\\ 
$\displaystyle\int^1_0f(x)\dx=0$ holds.} %Unterpunkt1
\Subitem{Justify why it follows that $f$ has a root in the interval $(0, 1)$ if it is assumed that $\displaystyle\int^1_0f(x)\dx=0$ holds. Sketch a possible graph of one such function $f$ in the coordinate system provided below.\leer

	\begin{center}
\newrgbcolor{uququq}{0.25098039215686274 0.25098039215686274 0.25098039215686274}
\psset{xunit=1.7cm,yunit=1.7cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1.6pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-2.331917201924157,-4.3427023216928)(2.3963904714973214,2.291781743631572)
\multips(0,-4)(0,1.0){7}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(-2.331917201924157,0)(2.3963904714973214,0)}
\multips(-2,0)(1.0,0){5}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,-4.3427023216928)(0,2.291781743631572)}
\psaxes[labelFontSize=\scriptstyle,showorigin=false,xAxis=true,yAxis=true,Dx=1.,Dy=1.,ticksize=-4pt 0,subticks=0]{->}(0,0)(-2.331917201924157,-4.3427023216928)(2.3963904714973214,2.291781743631572)[$x$,140] [$f(x)$,-40]
\antwort{\pscustom[linewidth=0.8pt,linecolor=uququq,fillcolor=uququq,fillstyle=solid,opacity=0.5]{\psplot{0.}{1.}{-4.3478260869565215*x^(3.0)-2.6289784566965458E-51*x^(2.0)+2.4456521739130435*x}\lineto(1.,0)\lineto(0.,0)\closepath}
\psplot[linewidth=2.pt,plotpoints=200]{-2.331917201924157}{2.3963904714973214}{-4.3478260869565215*x^(3.0)-2.6289784566965458E-51*x^(2.0)+2.4456521739130435*x}
\begin{scriptsize}
\rput[bl](-0.8218294109361456,1.6151303837353055){$f$}
\end{scriptsize}}
\end{pspicture*}
	\end{center}} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Begründung:

Berechnung der Nullstellen: $a\cdot x^3+b\cdot x=x\cdot (a\cdot x^2+b)=0$\\
Eine Nullstelle ist daher $x_1=0$.

Berechnung weiterer Nullstellen: $a\cdot x^2+b=0\Rightarrow x^2=-\frac{b}{a}$

Wenn die Koeffizienten $a$ und $b$ unterschiedliche Vorzeichen haben, dann gilt: $-\frac{b}{a}>0$.

Damit hat diese Gleichung zwei verschiedene reelle Lösungen und die Funktion $f$ hat insgesamt drei verschiedene Nullstellen.} %Lösung von Unterpunkt1
\Subitem{Mögliche Begründung:

Der Wert der Steigung der Tangente an den Graphen von $f$ an einer Stelle $x$ entspricht dem Wert $f'(x)$.

$f'(x)=3\cdot a\cdot x^2+b \Rightarrow f'(0)=b$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Begründung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Begründung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Vorgehensweise:

	$\displaystyle\int^1_0(a\cdot x^3+b\cdot x)$d$x=\left(a\cdot\frac{x^4}{4}+b\cdot\frac{x^2}{2}\right)\big|^1_0=0 \Rightarrow a=-2\cdot b$} %Lösung von Unterpunkt1
\Subitem{Mögliche Begründung:

	Das bestimmte Integral liefert die Summe der orientierten Flächeninhalte, die vom Graphen von $f$ und von der x-Achse begrenzt werden. Hätte $f$ keine Nullstelle im Intervall $(0;1)$, dann würde der Graph von $f$ in diesem Intervall entweder zur Gänze oberhalb der x-Achse (mit $f(x)>0$ für alle $x\in(0;1)$) oder zur Gänze unterhalb der x-Achse (mit $f(x)<0$ für alle $x\in(0;1)$) verlaufen. Somit wäre das bestimmte Integral von $f$ im Intervall $(0;1)$ entweder größer oder kleiner null, aber keinesfalls gleich null.

	Für einen möglichen Graphen von $f$ siehe oben.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine korrekte Beziehung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Begründung.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

