\rput[tl](0.26,311.2354074073986){$s_A(t),s_B(t)$ in $m$}
\rput[tl](8.3,20){$t$ in $s$}
\antwort{\psplot[linewidth=2.pt]{0.}{9}{(-0.--300.*x)/9.}
\psplot[linewidth=2.pt,plotpoints=200]{0}{9}{-3.0555555555555554*x^(2.0)+60.833333333333336*x}
\rput[tl](6.3,285.74962962962155){$s_B$}
\rput[tl](7.38,238.63955555554878){$s_A$}}
\end{pspicture*}
\end{center}} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$q_1=0,9$\\
$q_3=2,1$\\
Etwa die Hälfte der kontrollierten Fahrzeuge halten einen Tiefenabstand von mindestens 0,9 Sekunden und höchsten 2,1 Sekunden ein.} %Lösung von Unterpunkt1
\Subitem{Die im Kastenschaubild dargestellten Daten bestätigen etwa diese Erfahrungswerte.

Mögliche Begründung:\\
$130$\,km/h$=36,\dot{1}$\,m/s\\
$36,\dot{1}$\,m/s$\cdot 0,9$\,s$=32,5$\,m $\Rightarrow$ Mindestens drei Viertel der Kraftfahrer/innen halten einen Abstand von 30\,m und mehr ein.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtigen Werte sowie eine entsprechende Deutung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine korrekte Begründung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{ein möglicher Prozentsatz: 25\,\%

Mögliche Begründung:\\
Der Tiefenabstand von zwei Sekunden liegt zwischen dem Median und dem dritten Quartil.} %Lösung von Unterpunkt1
\Subitem{Mögliche Vorgehensweise:\\
Zufallsvariable $X=$ Anzahl der Kraftfahrlenker/innen, die den empfohlenen Mindestabstand eingehalten haben

$p=0,25$ ... Wahrscheinlichkeit, dass der empfohlene Mindestabstand eingehalten wurden\\
$n=10$ ... Anzahl der ausgewählten Messungen\\
$P(X\geq 6)\approx 0,0197$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Prozentsatz und entsprechender Begründung.

Toleranzintervall: $(20\,\%;25\,\%]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Wahrscheinlichkeit.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{zurückgelegter Weg $s_a(t)$: siehe Grafik.

Fahrzeug A fährt mit einer Geschwindigkeit von 120\,km/h.} %Lösung von Unterpunkt1
\Subitem{Zeit-Weg-Funktion $s_b$: siehe Grafik.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Graphen sowie die richtige Geschwindigkeit.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für den richtigen Graphen.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

