Das von Ricker entwickelte Modell zählt zu den Standardmodellen zur Beschreibung von Populationsentwicklungen. Dennoch können die mithilfe der Reproduktionsfunktion berechneten Werte mehr oder weniger stark von den beobachteten Werten abweichen.

\setcounter{subitemcounter}{1}
\Subitem{Nimm den beobachteten durchschnittlichen Lachsbestand von 1\,098 (im Zeitraum von 1908 bis 1911) als Ausgangswert, berechne damit für die jeweils vierjährigen Zeiträume von 1912 bis 1923 die laut Reproduktionsfunktion zu erwartenden durchschnittlichen Lachsbestände im Skeena River und trage die Werte in die nachstehende Tabelle ein!\vspace{0,3cm}

	\begin{center}
		\begin{tabular}{|l|C{5cm}|}\hline
	\cellcolor[gray]{0.9}Zeitraum&\cellcolor[gray]{0.9}berechneter Lachsbestand (in tausend Lachsen)\\ \hline
	01.01.1912 - 31.12.1915&\antwort{713}\\ \hline
	01.01.1916 - 31.12.1919&\antwort{626}\\ \hline
	01.01.1920 - 31.12.1923&\antwort{589}\\ \hline
	\end{tabular}
	\end{center}} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$n_0\approx 547$} %Lösung von Unterpunkt1
\Subitem{Mögliche Interpretation:\\
Im gegebenen Kontext gibt $n_0$ denjenigen Lachsbestand an, bei dem die Anzahl der Lachse der Nachfolgegeneration unverändert bleibt.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung.

Toleranzintervall für den Lachsbestand: $[547;548]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Ausgleichspunkt für eine korrekte Interpretation.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Vorgehensweise:\\
$R'(n)=0 \Rightarrow n_E=\frac{1}{b}$\\
$R\left(\frac{1}{b}\right)=\frac{a}{b\cdot e}$\\
$\Rightarrow E=\left(\frac{1}{b}\big|\frac{a}{b\cdot e}\right)$

Möglicher Nachweis:\\
$R''\left(\frac{1}{b}\right)=-\frac{a\cdot b}{e}<0$ für alle $a, b\in\mathbb{R}^+ \Rightarrow$ Maximumstelle} %Lösung von Unterpunkt1
\Subitem{$\frac{a}{b\cdot e}>\frac{1}{b} \Rightarrow a>e$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die Angabe der richtigen Koordinaten von $E$ und einen korrekten Nachweis.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Lösung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Histogramm: siehe oben.} %Lösung von Unterpunkt1
\Subitem{Tabelle: siehe oben.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für ein korrektes Histogramm.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die Angabe der richtigen Werte in der Tabelle.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

