\rput[tl](25.45,1.1389289667411646){Dichtefunktion 2}
\end{scriptsize}
\end{pspicture*}%Aufgabentext

\Subitem{Beschreibe, welcher Parameter verändert wurde und wie das zu sehen ist.} %Unterpunkt1
\Subitem{Beschreibe, woran zu sehen ist, dass der andere Parameter nicht verändert wurde.} %Unterpunkt2

\item %Aufgabentext

\Subitem{Bei einer bestimmten Abfüllmaschine erhält man durch Beobachtung folgende Daten: Die Füllmenge ist normalverteilt mit dem Erwartungswert $\mu=24.8$kg.
Wie groß darf bei dieser Produktion die Standardabweichung höchstens sein, wenn $95\%$ der Säcke im Inhalt höchstens um 0.5 kg vom Erwartungswert abweichen sollen?} %Unterpunkt1
\Subitem{Bei der Abfüllung gehen erfahrungsgemäß $8\%$ der Düngesäcke kaputt.
Berechne die Wahrscheinlichkeit, dass von 800 Säcken höchstens 50 kaputt gehen?} %Unterpunkt2

\item Bei einer bestimmten Abfüllmaschine kann die Füllmenge als normalverteilte Zufallsgröße mit einer Standardabweichung von 0,94 kg und einem Erwartungswert von 25 kg angenommen werden.
Laut Betriebsvorschrift müssen Säcke mit mehr als $\pm \frac{1}{2}$kg Abweichung vom Erwartungswert nachkorrigiert werden.%Aufgabentext

\Subitem{Berechne die Wahrscheinlichkeit, dass die Füllmenge eines zufällig ausgewählten Sackes nachkorrigiert werden muss.} %Unterpunkt1
\Subitem{Nach einer Untersuchung wird beschlossen, dass $97 \%$ aller Säcke (symmetrisch um den Erwartungswert) als korrekt abgefüllt betrachtet werden sollen.

Berechne, welche Abweichungen vom Erwartungswert nun bei der Abfüllung toleriert werden.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$P(x\leq 25)=0,84134\ldots$

Die Wahrscheinlichkeit beträgt rund $84,13\,\%$} %Lösung von Unterpunkt1
\Subitem{Die Differenz zw. der Sollfüllmenge und dem Erwartungswert entspricht der Standardabweichung. Der Bereich für $x<25$ besteht daher aus der Sigmaumgebung ($68\,\%$) und der Hälfte des außerhalb der Sigma Umgebung liegenden Bereiches, das sind ca. $16\,\%$.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Wahrscheinlichkeit.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine korrekte Beschreibung.} %Lösungschlüssel von Unterpunkt2

