\Subitem{Ein Punkt für die richtige Wahrscheinlichkeit.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Die Wahrscheinlichkeit, dass nachkorrigiert werden muss beträgt rund $59,5\%$} %Lösung von Unterpunkt1
\Subitem{$22,96\leq x \leq 27,04$} %%Lösung von Unterpunkt2

