\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,labels=none,Dx=1.,Dy=1.,ticksize=0pt 0,subticks=0]{->}(0,0)(0.,0.)(10.52,6.9)[$Q$,140] [$U(Q)$,-40]
\rput[tl](-0.28,0.28){0}
\rput[tl](0.06,-0.14){0}
\rput[tl](-0.54,5.14){$U_1$}
\rput[tl](6.9,-0.26){$Q_1$}
\antwort{\psline[linewidth=2.pt](0.,0.)(7.,5.)
\rput[tl](4.26,3.72){$U$}}
\begin{scriptsize}
\psdots[dotstyle=+](0.,5.)
\psdots[dotstyle=+](7.02,0.)
\end{scriptsize}
\end{pspicture*}
	\end{center}} %Unterpunkt1

Die in diesem Kondensator gespeicherte Energie $W$ kann mithilfe der Formel $W=\displaystyle\int^{Q_1}_0U(Q)\,\dx[Q]$ berechnet werden.	

\setcounter{subitemcounter}{1}	
\Subitem{Gib eine Formel für die gespeicherte Energie $W$ in Abhängigkeit von $U_1$ und $C$ an.} %Unterpunkt2

\item  Bei einem Ladevorgang kann die Spannung zwischen den Kondensatorplatten als Funktion $U$ in Abhängigkeit von der Zeit $t$ durch $U(t)=U^*\cdot\left(1-e^{\frac{t}{\tau}}\right)$ beschrieben werden. Dabei ist $U^*>0$ die an den Kondensator angelegte Spannung und $\tau>0$ eine für den Ladevorgang charakteristische Konstante. Der Ladevorgang beginnt zum Zeitpunkt $t=0$.

	Die Zeit, nach der die Spannung $U(t)$ zwischen den Kondensatorplatten $99\,\%$ der angelegten Spannung $U^*$ beträgt, wird als \textit{Ladezeit} bezeichnet.%Aufgabentext

\Subitem{Bestimme die Ladezeit eines Kondensators in Abhängigkeit von $\tau$.} %Unterpunkt1
\Subitem{Gib eine Formel für die momentane Änderungsrate der Spannung zwischen den Kondensatorplatten in Abhängigkeit von $t$ an und zeige mithilfe dieser Formel, dass die Spannung während des Ladevorgangs ständig steigt.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Grafik: siehe oben.} %Lösung von Unterpunkt1
\Subitem{$W=\displaystyle\int^{Q_1}_0 U(Q)\,\dx[Q]=\frac{1}{2}\cdot U_1\cdot Q_1=\frac{1}{2}\cdot C\cdot U_1^2$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Ausgleichspunkt für eine richtige Skizze.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine richtige Formel. Äquivalente Formeln sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Mögliche Vorgehensweise:\\
$0,99\cdot U^*=U^*\cdot\left(1-e^{-\frac{t}{\tau}}\right)$\\
$0,01=e^{-\frac{t}{\tau}}$

Ladezeit: $t=-\tau\cdot\ln(0,01)$ bzw. $t=\tau\cdot\ln(100)$} %Lösung von Unterpunkt1
\Subitem{Mögliche Vorgehensweise:\\
$U'(t)=\dfrac{e^{-\frac{t}{\tau}}\cdot U^*}{\tau}$\\
Es gilt: $U^*>0, \tau >0, e^{-\frac{t}{\tau}}>0 \Rightarrow U'(t)>0$ für alle $t\geq 0$.\\
Da $U'(t)>0$ für alle $t\geq 0$ gilt, ist $U$ während des Ladevorgangs streng monoton steigend.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Lösung. Äquivalente Schreibweisen der Lösung sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine richtige Formel und eine (sinngemäß) korrekte Begründung. Äquivalente Formeln sind als richtig zu werten.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

