Der durchschnittliche Preis für eine Film-DVD wird durch die Funktion $P$ in Abhängigkeit von der Zeit $t$ modelliert.

$P(t)=a\cdot b^t+11$ mit $a,b\in\mathbb{R}^+$

$t\ldots$ Zeit in Jahren mit $t=0$ für das Jahr 2002\\
$P(t)\ldots$ durchschnittlicher Preis für eine Film-DVD zur Zeit $t$ in Euro

\Subitem{Ermittle $a$ und $b$ so, dass $P$ für die Jahre 2002 und 2011 den durchschnittlichen Preis für eine Film-DVD im jeweiligen Jahr laut obigem Diagramm ergibt.\vspace{0,3cm}

$a=$\,\antwort[\rule{5cm}{0.3pt}]{$9,1$}\vspace{0,3cm}

$b=$\,\antwort[\rule{5cm}{0.3pt}]{$0,60579\ldots$}} %Unterpunkt1
%\Subitem{•} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$N(F)=\dfrac{16\cdot 1\,024\cdot 1\,024}{F}=\dfrac{16\,777\,216}{F}$} %Lösung von Unterpunkt1
%\Subitem{•} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Funktionsgleichung von $N$, wobei auch jeder Hinweis auf das Abrunden von $N(F)$ auf die nächstkleinere ganze Zahl als richtig zu werten ist.} %Lösungschlüssel von Unterpunkt1
%\Subitem{•} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$0,75+0,25\cdot 0,75^3=0,855\ldots$} %Lösung von Unterpunkt1
\Subitem{$0,75^3+3\cdot 0,25\cdot 0,75^2=0,843\ldots$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen der Wahrscheinlichkeit.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Berechnen der Wahrscheinlichkeit.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$P(0)=20,1 \Rightarrow a+11=20,1$

$P(9)=11,1 \Rightarrow a\cdot b^9+11=11,1$

$a=9,1$\vspace{0,5cm}

$b=\sqrt[9]{\dfrac{0,1}{9,1}}=0,60579\ldots$} %Lösung von Unterpunkt1
%\Subitem{•} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Ermitteln der beiden Werte, ein halber Punkt für nur einen richtigen Wert.} %Lösungschlüssel von Unterpunkt1
%\Subitem{•} %Lösungschlüssel von Unterpunkt2

\end{loesung}

