\rput[tl](4.603697966501601,9.374285714285689){\footnotesize IT-Fachwissen}
\antwort{\rput[tl](11,25){\footnotesize berufliches Fachwissen}}
\end{pspicture*}

\end{center}

\begin{aufgabenstellung}
\item Man geht davon aus, dass die Relevanz des beruflichen Fachwissens exponentiell abfällt und eine Halbwertszeit von 5 Jahren hat.

\Subitem{Zeichnen Sie in die Abbildung der Angabe den Verlauf der Relevanz des beruflichen
Fachwissens im Intervall $[0; 15]$ ein.}

\item Die Relevanz von Technologiewissen nimmt mit einer Halbwertszeit von 3 Jahren
exponentiell ab.

\Subitem{Stellen Sie diejenige Exponentialfunktion auf, die die Relevanz des Technologiewissens in Abhängigkeit von der Zeit beschreibt.}

\item Die Relevanz des Hochschulwissens lässt sich durch folgende Funktion $N$ beschreiben:

$$N(t)=100 \cdot e^{-0,0693 \cdot t}$$

$t$ \ldots Zeit in Jahren

$N(t)$ \ldots Relevanz des Hochschulwissens zur Zeit $t$ in \% des anfänglichen Hochschulwissens

\Subitem{Berechnen Sie, um wie viel Prozent die Relevanz des Hochschulwissens nach
7 Jahren bereits abgenommen hat.}

\item Die Relevanz des Schulwissens kann in den ersten Jahrzehnten durch eine lineare
Funktion beschrieben werden.

\Subitem{Lesen Sie aus der Abbildung in der Angabe die Steigung dieser linearen Funktion ab.}
\end{aufgabenstellung}


\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{siehe Grafik. Die Werte nach 5, 10 bzw. 15 Jahren müssen klar als 50\,\%, 25\,\% bzw. 12,5\,\% erkennbar sein.} %Lösung von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{Aufstellen der Exponentialfunktion:
$T(t)=100 \cdot 2^{-\frac{t}{3}}$

$t$ \ldots Zeit in Jahren

$T(t)$ \ldots Relevanz des Technologiewissens zur Zeit $t$ in Prozent der anfänglichen Relevanz des Wissens
} %Lösung von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$100-N(7) = 100 - 100 \cdot e^{-0,0693\cdot 7}=38,4 \ldots \approx 38$

Die Relevanz des Hochschulwissens hat um rund 38\,\% abgenommen.} %Lösung von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$k=-\frac{5}{2}$} %Lösung von Unterpunkt1

\end{loesung}

202.content:
Der \textit{Baumkronenpfad} ist eine Brückenstrecke durch einen Teil des Schönbrunner Tiergartens.

\begin{center}
\includegraphics[width=0.9\textwidth]{../_database/Bilder/201-baumkronenpfad.eps}
\end{center}

\begin{aufgabenstellung}
\item Auf dem Schild zum Baumkronenpfad ist zu lesen:\\
"`Der Baumkronenpfad hat ein sanftes Gefälle von 8\,\%."' 

Dabei wird der Baumkronenpfad vereinfacht als geradlinig angenommen. Die horizontale Entfernung zwischen Startpunkt und Endpunkt beträgt 160\,m.%Aufgabentext

\Subitem{Berechne den Höhenunterschied zwischen Startpunkt und Endpunkt.} %Unterpunkt1
\Subitem{Berechne den Neigungswinkel des Baumkronenpfads.} %Unterpunkt2

\item Auf dem Schild zum Baumkronenpfad ist zu lesen: "`Der Baumkronenpfad kann schwingen"'.

In der nachstehenden Grafik ist das Auf-und-ab-Schwingen des Baumkronenpfads an einer bestimmten Stelle dargestellt.

\begin{center}
\psset{xunit=1.5cm,yunit=22cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-0.8,-0.12)(9.3,0.22)
\multips(0,-0.1)(0,0.05){16}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,0)(28.596218020022217,0)}
\multips(0,0)(1,0){34}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,-0.4337293600556306)(0,0.3647922432255976)}
\psaxes[comma,showorigin=false,labelFontSize=\scriptstyle,xAxis=true,yAxis=true,Dx=1,Dy=0.05,ticksize=-2pt 0,subticks=0]{->}(0,0)(0,-0.12)(9.3,0.22)
\psplot[linewidth=0.8pt,plotpoints=2000]{0}{28.596218020022217}{0.2*2.718281828459045^(-0.54*x)*SIN(4*x)}
\psplot[linewidth=0.8pt,linestyle=dashed,dash=3pt 3pt,plotpoints=200]{0}{28.596218020022217}{0.2*2.718281828459045^(-0.54*x)}
\begin{scriptsize}
\rput[bl](0.22150166852058107,0.20){Auslenkung in Metern}
\rput[bl](7.5,0.012){Zeit $t$ in Sekunden}
\rput[bl](1.5,0.1){$f$}
\end{scriptsize}
\end{pspicture*}
\end{center}

In der obigen Grafik ist die sogenannte "`Einhüllende"' strichliert eingezeichnet. Es handelt sich dabei um eine Funktion $f$ mit $f(t)=c\cdot a^t$.
%Aufgabentext

\Subitem{Lese aus der Grafik den Parameter $c$ ab.} %Unterpunkt1
\Subitem{Begründe mathematisch, warum für den Parameter $a$ dieser Funktion $f$ gilt: $0<a<1$.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Höhenunterschied in Metern: $160\cdot 0,08=12,8$} %Lösung von Unterpunkt1
\Subitem{$\tan(\alpha)=0,08 \Rightarrow \alpha=4,57\ldots^\circ$

Auch $\alpha=-4,57\ldots^\circ$ ist als richtig zu werten.\\
Auch die Berechnung des Winkels im Bogenmaß ist als richtig zu werten.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Höhenunterschied.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für den richtigen Neigungswinkel.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$c=f(0)=0,2$} %Lösung von Unterpunkt1
\Subitem{Da die gegebene Exponentialfunktion streng monoton fallend ist, gilt für den Parameter $a$: $0<a<1$.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Parameterwert von $c$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine entsprechende Begründung.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

