\begin{aufgabenstellung}
\item Direkt unter der Wasseroberfläche beträgt der Druck 1\,Bar. Der Druck nimmt mit zunehmender Wassertiefe gleichmäßig zu, und zwar um 1\,Bar je 10 Meter Wassertiefe.%Aufgabentext

\Subitem{Berechne, in welcher Wassertiefe ein Druck von 3,9\,Bar herrscht.} %Unterpunkt1

\item Die Abnahme der Beleuchtungsstärke erfolgt unter Wasser exponentiell und kann näherungsweise durch die Funktion $f$ beschrieben werden. Der Graph von $f$ ist in der nachstehenden Abbildung dargestellt.%Aufgabentext

\begin{center}
\psset{xunit=0.3cm,yunit=0.12cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1pt,arrowsize=3pt 2,arrowinset=0.25}
