\multips(0,0)(0,5){13}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=lightgray]{c-c}(0,0)(35.76767441860468,0)}
\multips(0,0)(2,0){21}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=lightgray]{c-c}(0,0)(0,57.01134408953373)}
\psaxes[labelFontSize=\scriptstyle,xAxis=true,showorigin=false,ylabelFactor=\,000,yAxis=true,Dx=2,Dy=10,ticksize=-2pt 0,subticks=0]{->}(0,0)(0,0)(35.76767441860468,57.01134408953373)
\psplot[linewidth=1pt,plotpoints=200]{0}{35.76767441860468}{50*(0.1)^(1/(20))^(x)}
\begin{scriptsize}
\rput[tl](-5.5,55.960981557689706){$f(x)$ in Lux}
\rput[tl](24,-4.5){Wassertiefe $x$ in Metern}
\rput[bl](1.1553488372093026,49.308685522677585){$f$}
\end{scriptsize}
\end{pspicture*}
\end{center}

\Subitem{Lies aus der obigen Abbildung ab, in welcher Tiefe die Beleuchtungsstärke nur mehr 10\,\% ihres Anfangswerts beträgt.} %Unterpunkt1
\Subitem{Erstelle eine Gleichung der Funktion $f$.} %Unterpunkt2

\item Durch eine bestimmte Tauchermaske werden alle Gegenstände unter Wasser um ein Drittel größer wahrgenommen, als sie tatsächlich sind.%Aufgabentext

\Subitem{Ermittle, um wie viel Prozent die tatsächliche Größe kleiner als die wahrgenommene Größe ist.} %Unterpunkt1

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$3,9=1+0,1\cdot x\Rightarrow x=29$

In einer Wassertiefe von 29 Metern herrscht ein Druck von 3,9\,Bar.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Wassertiefe.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{In einer Tiefe von 20 Metern beträgt die Beleuchtungsstärke 5\,000 Lux.} %Lösung von Unterpunkt1
\Subitem{$f(x)=a\cdot b^x \Rightarrow a=50\,000$

$50\,000=50\,000\cdot b^{20} \Rightarrow b=\sqrt[20]{0,1}=0,8912\ldots\approx 0,891$

$f(x)=50\,000\cdot 0,891^x$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Meerestiefe. Toleranzintervall: $[19,5; 20,5]$} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Funktionsgleichung. Geringfügige Abweichungen aufgrund der Verwendung anderer Punkte sind zulässig.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{tatsächliche Größe: $x$

wahrgenommene Größe: $w=\dfrac{4}{3}\cdot x \Rightarrow x=\dfrac{3}{4}\cdot w$

Die tatsächliche Größe ist um 25\,\% kleiner als die wahrgenommene Größe.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Prozentangabe.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

