\end{pspicture*}
\end{center}%Aufgabentext

\Subitem{Erkläre, welchen Grad diese Polynomfunktion mindestens haben muss.} %Unterpunkt1

\item Im Vergnügungspark gibt es ein Kino.

Fiona sitzt $a$ Meter von der Leinwand entfernt (Punkt $F$). Der Höhenwinkel zum unteren Ende der Leinwand (Punkt $Q$) wird mit $\alpha$ bezeichnet, der Höhenwinkel zum oberen Ende der Leinwand (Punkt $P$) wird mit $\beta$ bezeichnet.

\begin{center}
\psset{xunit=0.6cm,yunit=0.6cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1pt,arrowsize=3pt 2,arrowinset=0.25}
