\end{center}%Aufgabentext

\Subitem{Erstelle eine Formel für die Berechnung der Höhe $h$ der Leinwand aus $a$, $\alpha$ und $\beta$.\vspace{0,5cm}

$h=\,\antwort[\rule{3cm}{0.3pt}]{a\cdot\tan(\beta)-a\cdot\tan(\alpha)=a\cdot\left(\tan(\beta)-\tan(\alpha)\right)}$} %Unterpunkt1

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$4,1=9-x^2$

$x^2=4,9$

$x=\pm 2,213\ldots$

Der Festwagen darf rund 4,42\,m breit sein.} %Lösung von Unterpunkt1
\Subitem{$\displaystyle\int^3_{-3}(9-x^2)\dx=36$

Der Flächeninhalt der benötigten Folie beträgt 36\,m$^2$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige (Maximal-)Breite.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für den richtigen Flächeninhalt der Folie.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Diese Polynomfunktion hat im dargestellten Intervall 2 lokale Extremstellen. Somit muss die 1. Ableitung dieser Funktion 2 Nullstellen haben, also mindestens eine Polynomfunktion 2. Grades sein. Somit muss die gegebene Polynomfunktion mindestens Grad 3 haben.

\textit{oder:}

Eine Gerade parallel zur $x$-Achse hat 3 Schnittpunkte mit dem Graphen der Funktion. Somit muss die gegebene Polynomfunktion mindestens Grad 3 haben.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine entsprechende Formulierung.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{rechtwinkliges Dreieck $FPS$: $\tan(\beta)=\dfrac{\overline{SP}}{a}\Rightarrow \overline{SP}=a\cdot\tan(\beta)$

rechtwinkliges Dreieck $FQS$: $\tan(\alpha)=\dfrac{\overline{SQ}}{a}\Rightarrow \overline{SQ}=a\cdot\tan(\alpha)$

$h=\overline{SP}-\overline{SQ}$

$h=a\cdot\tan(\beta)-a\cdot\tan(\alpha)=a\cdot\left(\tan(\beta)-\tan(\alpha)\right)$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine entsprechende Gleichung.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

