\begin{aufgabenstellung}
\item Zug Nr. 3 fährt um 12:00 Uhr in Altheim ab.\\
Zur Nr. 4 fährt um 14:40 in Burghausen ab.\\
Auf der Fahrt zu ihren Zielbahnhöfen begegnen die beiden Züge einander.%Aufgabentext

\Subitem{Lies aus dem obigen Bildfahrplan ab, wann und wie weit von Burghausen entfernt die beiden Zügen einander begegnen.} %Unterpunkt1

\item %Aufgabentext

\Subitem{Argumentiere, dass die Züge Nr. 2 und Nr. 4 mit der gleichen Geschwindigkeit fahren.} %Unterpunkt1

\item Die Fahrt eines Zuges Nr. 5 wird durch die Funktion $s$ beschrieben. Es gilt:

$s(t)=-80\cdot t+1\,160$

$t\ldots$ Zeit nach Mitternacht in h\\
$s(t)\ldots$ Entfernung von Altheim zur Zeit $t$ in km%Aufgabentext

\Subitem{Bestimme die Uhrzeit, zu der Zug Nr. 5 in Burghausen abfährt.} %Unterpunkt1

\item Eine Eisenbahnstrecke hat eine Länge von 200\,km. Nach einer Sanierung der Gleise können die Züge mit einer um 10\,km/h höheren Geschwindigkeit fahren. Die Fahrzeit wird dadurch um eine halbe Stunde vermindert.\\
Zur Verdeutlichung sind die Angaben in der nachstehenden Tabelle dargestellt.\\
$t$ ist dabei die Fahrzeit vor der Sanierung in Stunden.

\begin{center}
\begin{tabular}{|c|c|c|c|}\cline{2-4}
\multicolumn{1}{c}{\phantom{text}}&\cellcolor[gray]{0.9}Streckenlänger in km&\cellcolor[gray]{0.9}Geschwindigkeit in km/h&\cellcolor[gray]{0.9}Fahrzeit in h\\ \hline \renewcommand{\arraystretch}{2}
\cellcolor[gray]{0.9}nach der Sanierung&$200$&$\left(\frac{200}{t}+10\right)$&$\left(t-\frac{1}{2}\right)$\\ \hline
\end{tabular}
\end{center}%Aufgabentext

\Subitem{Berechne $t$.} %Unterpunkt1

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Die beiden Züge begegnen einander um 15:00 Uhr, 20\,km von Burghausen entfernt.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Zeit- und Distanzangabe.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{Die beiden Zügen benötigen für die Strecke Burghausen-Altheim gleich lang, sie fahren also mit der gleichen Geschwindigkeit.

\textit{oder:}

Die zugehörigen Geraden im Bildfahrplan haben die gleiche Steigung.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für ein entsprechendes Argument.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$s(t)=200$

\textit{oder:}

$-80\cdot t+1\,160=200$\vspace{0,2cm}

$t=\dfrac{200-1\,160}{-80}=12$\vspace{0,2cm}

Zug Nr. 5 fährt um 12 Uhr in Burghausen ab.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die entsprechende Uhrzeit.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$200=\left(\dfrac{200}{t}+10\right)\cdot\left(t-\dfrac{1}{2}\right)$\vspace{0,3cm}

$t_1=3,422\ldots$

$(t_2=-2,922\ldots)$

Die Fahrzeit vor der Sanierung betrug etwa 3,42\,h} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Fahrzeit.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

218.content:
Auf einer Teststrecke werden Messungen durchgeführt.%Aufgabentext

\begin{aufgabenstellung}
\item Die Teststrecke beginnt bei einem Stoppschild. Die Messergebnisse für ein Auto auf dieser entsprechenden Strecke sind in folgender Tabelle angegeben:

\begin{center}
\begin{tabular}{|l|c|c|c|}\cline{2-4}
\multicolumn{1}{c|}{\phantom{text}}&\cellcolor[gray]{0.9}am Stoppschild&\cellcolor[gray]{0.9}Messung 1&\cellcolor[gray]{0.9}Messung 2\\ \hline
\cellcolor[gray]{0.9}Zeit $t$ in min&0&1&2,5\\ \hline
\cellcolor[gray]{0.9}zurückgelegter Weg $s_1(t)$ in km&0&1&3\\ \hline
\end{tabular}
\end{center}

Der zurückgelegte Weg soll in Abhängigkeit von der Zeit $t$ im Zeitintervall $[0;2,5]$ durch eine Polynomfunktion $s_1$ mit $s_1(t)=a\cdot t^2+b\cdot t+c$ beschrieben werden.%Aufgabentext

\Subitem{Berechne die Koeffizienten der Funktion $s_1$.} %Unterpunkt1

\item Der zurückgelegte Weg eines anderen Autos kann näherungsweise durch die Funktion $s_2$ beschrieben werden:

$s_2(t)=-\frac{1}{3}\cdot t^3+2\cdot t^2+\frac{1}{3}\cdot t$ mit $0\leq t\leq 3$

$t\ldots$ Zeit in min\\
$s_2(t)\ldots$ zurückgelegter Weg zur Zeit $t$ in km%Aufgabentext

\Subitem{Überprüfe nachweislich, ob die Geschwindigkeit dieses Autos zu Beginn des angegebenen Zeitintervalls null ist.} %Unterpunkt1
\Subitem{Berechne, nach welcher Zeit $t_0$ die Beschleunigung des Autos im angegebenen Zeitintervall null ist.} %Unterpunkt2

\item Die Geschwindigkeit eines anderen Autos kann im Zeitintervall $[0;3]$ näherungsweise durch die Funktion $v_3$ beschrieben werden. Der Graph dieser Funktion $v_3$ ist in der nachstehenden Abbildung dargestellt.

\begin{center}
\psset{xunit=2.3cm,yunit=0.2cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-0.31804347826086965,-2.8285714285714145)(3.3310869565217396,27.94285714285711)
\multips(0,0)(0,5){7}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,0)(3.3310869565217396,0)}
\multips(0,0)(0.5,0){8}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=gray]{c-c}(0,0)(0,27.94285714285711)}
\psaxes[comma,labelFontSize=\scriptstyle,xAxis=true,yAxis=true,Dx=0.5,Dy=5,ticksize=-2pt 0,subticks=0]{->}(0,0)(0,0)(3.3310869565217396,27.94285714285711)[Zeit in s,140] [Geschwindigkeit in m/s,-40]
\psline[linewidth=1pt](0,15)(1,15)
\psline[linewidth=1pt](1,15)(3,25)
\begin{scriptsize}
\rput[bl](2.05054347826087,18.771428571428554){$v_3$}
\end{scriptsize}
\end{pspicture*}
\end{center}%Aufgabentext

\Subitem{Erstelle eine Gleichung der zugehörigen Weg-Zeit-Funktion $s_3$ im Zeitintervall $[1;3]$ mit $s_3(1)=15$.} %Unterpunkt1

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$s_1(0)=0$\\
$s_1(1)=1$\\
$s_1(2,5)=3$

\textit{oder:}

$0=a\cdot 0^2+b\cdot 0+c$\\
$1=a\cdot 1^2+b\cdot 1+c$\\
$3=a\cdot 2,5^2+b\cdot 2,5+c$

Berechnung mittels Technologieeinsatz:

$a=\frac{2}{15}$,\quad $b=\frac{13}{15}$,\quad $c=0$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtigen Koeffizienten.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$v_2(t)=s'_2(t)=-t^2+4\cdot t+\frac{1}{3}$

$v_2(0)=\frac{1}{3}\neq 0$

Das Auto hatte zu Beginn des angegebenen Zeitintervalls eine Geschwindigkeit ungleich 0.} %Lösung von Unterpunkt1
\Subitem{$a_2(t)=s''_2(t)=-2\cdot t+4$

$a_2(t_0)=0 \Rightarrow t_0=2$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für einen entsprechenden Nachweis.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine entsprechende Berechnung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$v_3(t)=5\cdot t+10$ mit $1\leq t\leq 3$\vspace{0,2cm}

Integrieren ergibt: $s_3(t)=\frac{5}{2}\cdot t^2+10\cdot t+C$\vspace{0,2cm}

Wegen $s_3(1)=15$ gilt: $s_3(t)=\frac{5}{2}\cdot t^2+10\cdot t+\frac{5}{2}$ mit $1\leq t\leq 3$

$t\ldots$ Zeit in s\\
$s_3(t)\ldots$ zurückgelegter Weg zur Zeit $t$ in m} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Gleichung.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

219.content:
Bei einem Therapieverfahren wird die Körpertemperatur bewusst stark erhöht (künstliches Fieber). Die  Grafik dokumentiert näherungsweise den Verlauf des künstlichen Fiebers bei einer solchen Behandlung.

\begin{center}
\psset{xunit=1.4cm,yunit=0.9cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-0.64,35.52)(6.08,42.74)
\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,Dx=1,Dy=1,Oy=36,ticksize=-2pt 0,subticks=0]{->}(0,36)(0,36)(6.08,42.74)[Zeit in h,140] [Körpertemperatur in $^\circ$C,-40]
\psplot[linewidth=1pt,plotpoints=200]{0}{5}{-0.18*x^(3)+0.85*x^(2)+0.6*x+36.6}
\begin{scriptsize}
\rput[bl](0.82,37){$f$}
\end{scriptsize}
\end{pspicture*}
\end{center}

Die Funktion $f$ beschreibt den Zusammenhang zwischen Zeit und Körpertemperatur:

$f(t)=-0,18\cdot t^3+0,85\cdot t^2+0,6\cdot t+36,6$

$t\ldots$ Zeit in Stunden (h) mit $0\leq t\leq 5$\\
$f(t)\ldots$ Körpertemperatur zur Zeit $t$ in $^\circ$C%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Berechne denjenigen Zeitpunkt, zu dem die Körpertemperatur 37\,$^\circ$C beträgt.} %Unterpunkt1

\item %Aufgabentext

\Subitem{Dokumentiere, wie die maximale Körpertemperatur im angegebenen Zeitintervall mithilfe der Differenzialrechnung berechnet werden kann.} %Unterpunkt1
\Subitem{Begründe, warum der Graph einer Polynomfunktion 3. Grades höchstens 2 Extrempunkte haben kann.} %Unterpunkt2

\item Die mittlere Körpertemperatur $\overline{f}$ während der 5 Stunden andauernden Behandlung soll ermittelt werden.

Die mittlere Körpertemperatur in einem Zeitintervall $[t_1;t_2]$ ist:\vspace{0,2cm}

$\overline{f}=\dfrac{1}{t_2-t_1}\displaystyle\int^{t_2}_{t_1}f(t)\dx[t]$%Aufgabentext

\Subitem{Berechne die mittlere Körpertemperatur $\overline{f}$ im Zeitintervall $[0;5]$.} %Unterpunkt1

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$-0,18\cdot t^3+0,85\cdot t^2+0,6\cdot t+36,6=37$

$t=0,429\ldots \Rightarrow t\approx 0,43$\,h} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Zeitpunkt.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{Dazu muss das Maximum der Funktion $f$ ermittelt werden: Man berechnet die Nullstellen der 1. Ableitung $f'$. Dann berechnet man die Funktionswerte an diesen Stellen und an den Randstellen. Die größte dieser Zahlen ist der maximale Funktionswert.} %Lösung von Unterpunkt1
\Subitem{Die 1. Ableitung einer Polynomfunktion 3. Grades ist eine quadratische Funktion. Eine quadratische Funktion hat höchstens 2 Nullstellen. Daher kann der Graph der Polynomfunktion 3. Grades nur höchsten 2 Extrempunkte haben.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine entsprechende Erklärung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine entsprechende Begründung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$\overline{f}=\frac{1}{5}\cdot\displaystyle\int^5_0f(t)\dx[t]=39,55\ldots\approx 39,6$\vspace{0,2cm}

Die mittlere Körpertemperatur beträgt rund 39,6\,$^\circ$C.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige mittlere Körpertemperatur.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

220.content:
Bei einem bestimmten Unternehmen werden die Produktionskosten untersucht. Im ersten Jahr gilt modellhaft für dieses Unternehmen:

$K(x)=0,01\cdot x^3-3\cdot x^2+350\cdot x+20\,000$

$x\ldots$ Produktionsmenge in ME ($x\in\mathbb{R}^+_0)$\\
$K(x)\ldots$ Produktionskosten in GE%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Berechne, um wie viel sich die Grenzkosten bei einem Produktionsumfang von $x=50$\,ME vom tatsächlichen Zuwachs der Kosten (das heißt bei Erhöhung des Produktionsumfangs von 50\,ME auf 51\,ME) bei diesem Unternehmen unterscheidet.} %Unterpunkt1

Für $K(x)$ gilt die Aussage: "`Die Grenzkosten sind stets positiv."'

\Subitem{Begründe, warum diese Aussage richtig ist.} %Unterpunkt2

\item Für die Festlegung des Produktionsplans ist es erforderlich, die durchschnittlichen Kosten pro erzeugter ME in Abhängigkeit von der Produktionsmenge zu kennen. Die Stückkostenfunktion gibt die durchschnittlichen Kosten pro erzeugter ME an.%Aufgabentext

\Subitem{Stelle die Stückkostenfunktion $\overline{K}(x)$ dieses Unternehmens auf.} %Unterpunkt1
\Subitem{Berechne, bei welcher Produktionsmenge die durchschnittlichen Stückkosten für dieses Unternehmen am geringsten sind.} %Unterpunkt2

\item Im zweiten Jahr können die Produktionskosten dieses Unternehmens durch eine Funktion $f$ mit $f(x)=a\cdot x^2+100\cdot x+c$ mit $a,b,c\in\mathbb{R}, a\neq 0, x\in\mathbb{R}^+_0$ modellhaft beschrieben werden.%Aufgabentext

\Subitem{Ermittle alle Werte für $a$ so, dass ein progressiver Verlauf der Produktionskosten vorliegt.} %Unterpunkt1

Für die Produktionskosten gilt:

\begin{itemize}
\item Die Fixkosten der Produktion betragen 15\,000\,GE
\item die Produktionskosten für 100\,ME betragen 30\,000\,GE.
\end{itemize}

\Subitem{Bestimme die Werte von $a$ und $c$.\vspace{0,3cm}

$a=$\,\antwort[\rule{3cm}{0.3pt}]{$0,5$}\vspace{0,3cm}

$c=$\,\antwort[\rule{3cm}{0.3pt}]{$15\,000$}} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$K'(50)=125$

$K(51)-K(50)=123,51$

Unterschied: $1,49$\,GE} %Lösung von Unterpunkt1
\Subitem{$K(x)$ ist im angegebenen Bereich monoton steigend, deshalb ist $K'(x)$ stets positiv.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen des Unterschieds.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Begründen.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$\overline{K}(x)=0,01\cdot x^2-3\cdot x+350+\frac{20\,000}{x}$} %Lösung von Unterpunkt1
\Subitem{$\overline{K}'(x)=0 \Rightarrow x=180,64\ldots$

Bei einer Produktion von rund 181\,ME sind die durchschnittlichen Stückkosten am geringsten.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Stückkostenfunktion.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Berechnen der Produktionsmenge.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$a>0$} %Lösung von Unterpunkt1
\Subitem{$a=0,5$ und $c=15\,000$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Ermitteln der Werte.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das Bestimmen der beiden richtigen Werte.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

