\Subitem{Berechne den in der obigen Abbildung markierten Winkel $\alpha$.} %Unterpunkt1

\item Die Bahnkurve einer gestoßenen Kugel lässt sich näherungsweise durch den Graphen der quadratischen Funktion $h$ beschreiben:

$h(x)=-0,05\cdot x^2+0,75\cdot x+2$ mit $x\geq 0$

$x\ldots$ horizontale Entfernung der Kugel von der Abstoßstelle in m\\
$h(x)\ldots$ Höhe der Kugel über dem Boden bei der horizontalen Entfernung $x$ in m%Aufgabentext

\Subitem{Ermittle, in welcher horizontalen Entfernung von der Abstoßstelle die Kugel auf dem Boden aufschlägt.} %Unterpunkt1

\item Für die bei den Männern verwendeten Kugeln gelten folgende Vorgaben:

\begin{itemize}
\item Die Masse beträgt 7\,257\,g.
\item Der Durchmesser der Kugel liegt zwischen 11\,cm und 13\,cm
\end{itemize}Aufgabentext

Eine Messing-Eisen-Legierung hat eine Dichte von 8,2\,g/cm$^3$.\\
Die Masse $m$ ist das Produkt aus Volumen $V$ und Dichte $\rho$, also $m=V\cdot\rho$.

\Subitem{Überprüfe nachweislich, ob man aus dieser Messing-Eisen-Legierung eine Kugel herstellen kann, die diese Vorgaben erfüllt.} %Unterpunkt1

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Steigung $k$ der linearen Funktion $f$: $k=\dfrac{0,34}{2,5}=0,136$

$f(t)=0,136\cdot t+17,68$

$t\ldots$ Zeit in Jahren\\
$f(t)\ldots$ Weltrekordweite zur Zeit $t$ in m} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Gleichung.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$\alpha=2\cdot\arcsin\left(\dfrac{6}{20}\right)=34,915\ldots^\circ\approx 34,92^\circ$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Winkel.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$h(x)=0$

\textit{oder:}

$-0,05\cdot x^2+0,75\cdot x+2=0$

$x_1=17,310\ldots$,\quad $(x_2=-2,310\ldots)$

Die Kugel schlägt in einer horizontalen Entfernung von rund 17,31\,m auf dem Boden auf.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige horizontale Entfernung.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$7\,257=\dfrac{4}{3}\cdot r^3\cdot\pi\cdot 8,2$\vspace{0,3cm}

$r=\sqrt[3]{\dfrac{7\,257\cdot 3}{8,2\cdot 4\cdot\pi}=5,95\ldots}$\vspace{0,3cm}

$d=2\cdot r=11,91\ldots$

Der Durchmesser einer derartigen Kugel beträgt rund 11,9\,cm und liegt im angegebenen Bereich.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für einen entsprechenden Nachweis.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

