\psline[linewidth=0.8pt,fillcolor=black,fillstyle=solid,opacity=0.1](60,0.5)(60,2.5)
\psline[linewidth=0.8pt,fillcolor=black,fillstyle=solid,opacity=0.1](35,1.5)(50,1.5)
\psline[linewidth=0.8pt,fillcolor=black,fillstyle=solid,opacity=0.1](65,1.5)(75,1.5)
\end{pspicture*}
\end{center}%Aufgabentext

\Subitem{Lies ab, wie viel Prozent der Schüler/innen mindestens 50 Punkte erreicht haben.} %Unterpunkt1
\Subitem{Ermittle die Spannweite der Punktezahlen.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Säulendiagramm:

\psset{xunit=1cm,yunit=1cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1pt,arrowsize=3pt 2,arrowinset=0.25}
