\multips(0,0)(100,0){1}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=lightgray]{c-c}(0,0)(0,5.48)}
\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,labels=y,Dx=1,Dy=1,ticksize=-2pt 0,subticks=0]{->}(0,0)(0,0)(7.4,5.68)[\scriptsize Klassen,140] [\scriptsize Häufigkeiten,-40]
