%Aufgabentext

\begin{aufgabenstellung}
\item Bettina macht eine 2-stündige Fahrradtour. Ihre Geschwindigkeit kann dabei näherungsweise durch die Funktion $v$ beschrieben werden.

$v(t)=-0,08\cdot t^2+16$ mit $0\leq t\leq 2$

$t\ldots$ Zeit in h mit $t=0$ für den Beginn der Fahrradtour\\
$v(t)\ldots$ Geschwindigkeit zum Zeitpunkt $t$ in km/h%Aufgabentext

\Subitem{Berechne die Zeitdauer, die Bettina für die ersten 10\,km dieser Fahrradtour benötigt.} %Unterpunkt1
\Subitem{Berechne die Beschleunigung zum Zeitpunkt $t=1$. Gib auch die zugehörige Einheit an.} %Unterpunkt2

\item Der empfohlene Reifendruck eines Fahrradreifens sinkt mit zunehmender Breite des Reifens.\\
Für einen empfohlenen Reifendruck von 2\,bar bis 9\,bar kann der empfohlene Reifendruck näherungsweise durch die Funktion $p$ beschrieben werden.\vspace{0,2cm}

$p(x)=19,1\cdot e^{-0,0376\cdot x}$

$x\ldots$ Breite des Reifens in mm\\
$p(x)\ldots$ empfohlener Reifendruck bei der Breite $x$ in bar

\Subitem{Ermittle das größtmöglichste Intervall für die Breite des Reifens, für das sich ein empfohlener Reifendruck von 2\,bar bis 9\,bar ergibt.}

\Subitem{Interpretiere das Ergebnis der nachstehenden Berechnung unter Angabe der zugehörigen Einheiten im gegebenen Sachzusammenhang.

$p(30)-p(20)\approx -2,8$}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$\displaystyle\int^{t_1}_0 v(t)\dx[t]=10$

Berechnung mittels Technologieeinsatz: $t_1=0,62\ldots$

Bettina benötigt für die ersten 10\,km rund 0,6\,h.} %Lösung von Unterpunkt1
\Subitem{$a(t)=v'(t)=-0,16\cdot t$

$v'(1)=-0,16$

Die Beschleunigung zum Zeitpunkt $t=1$ beträgt $-0,16$\,km/h$^2$.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein halber Punkt für das richtige Berechnen der Zeitdauer.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein halber Punkt für das richtige Berechnen der Beschleunigung, ein halber Punkt für das Angeben der richtigen Einheit.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$p(x)=9 \Rightarrow x=20,0\ldots$\\
$p(x)=2 \Rightarrow x=60,0\ldots$

größtmöglichstes Intervall: $[20,0\ldots; 60,0\ldots]$} %Lösung von Unterpunkt1
\Subitem{Der für einen 30\,mm breiten Reifen empfohlene Reifendruck ist um rund 2,8\,bar geringer als der für einen 20\,mm breiten Reifen empfohlene Reifendruck.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Ermitteln des größtmöglichen Intervalls.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Interpretieren unter Angabe der zugehörigen Einheiten im gegebenen Sachzusammenhang.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

