\Subitem{Ein Punkt für das richtige Berechnen des Prozentsatzes.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$f(t)=k\cdot t+d$

$k=\dfrac{6,140-3,700}{30}=0,081\dot{3}$

$d=f(0)=3,700$

$f(t)=0,081\dot{3}\cdot t+3,700$} %Lösung von Unterpunkt1
\Subitem{$f(50)=7,7\dot{6}$

$\dfrac{7,7\dot{6}-7,790}{7,790}=-0,0029\ldots$

Abweichung: rund $-0,3$\,\%} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Funktionsgleichung von $f$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Berechnen der Abweichung in \%. Auch die Angabe von 0,3\,\% ist richtig.} %Lösungschlüssel von Unterpunkt2

