\Subitem{$f'(x)=\frac{x}{4}$

$f'(4)=1$

$g'(x)=a\cdot(3\cdot x^2-16)$

$g'(4)=32\cdot a$

$32\cdot a=1$

$a=\frac{1}{32}$} %Lösung von Unterpunkt1
\Subitem{Die Funktion $g$ ist eine Polynomfunktion 3. Grades

\textit{oder:}

Die Funktion $g''$ ist lineare und hat nur 1 Nullstelle.\\
(Die Funktion $g$ kann also nur 1 Wendepunkt haben).} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen von $a$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Begründen.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$u=5\cdot 2\cdot 3\cdot\sin(36^\circ)=17,63\ldots$

$u=17,6$\,cm} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen des Umfangs $u$.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$g(x)=-a\cdot x^2+2\cdot b$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Funktionsgleichung von $g$.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

