\end{tabular}
\end{center}%Aufgabentext

\Subitem{Ermittle $b$ und $c$.} %Unterpunkt1
\Subitem{Ermittle mithilfe der Funktion $a$ und der Abbildung im Einleitungstext den Zeitpunkt $t_3$, zu dem die Beschleunigung $3,7$\,m/s$^2$ beträgt.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$v_1(t)=25\cdot t$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Funktionsgleichung von $v_1$.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$v_2(t_2)=130$

$t_2=6,21\ldots$\,s} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen von $t_2$.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$a(80)=6,7$

$a(160)=1,4$

$b=-0,13825$ und $c=15,84$} %Lösung von Unterpunkt1
\Subitem{$a(v_3)=3,7$

$v_3=118,054\ldots$

Aus der Abbildung folgt: $t_3\approx 5,5$\,s} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Ermitteln der beiden Werte.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Ermitteln von $t_3$.\\
Toleranzintervall für $t_3$: $[4; 6]$} %Lösungschlüssel von Unterpunkt2

\end{loesung}

