\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Gib an, zwischen welchen aufeinanderfolgenden Monaten (inkl. Jahr) die größte absolute Änderung zu verzeichnen war und berechne diese.} %Unterpunkt1
\Subitem{Berechne die relative Änderung von 08-2022 auf 09-2022 und interpretiere das Ergebnis im Kontext.} %Unterpunkt2

\item  %Aufgabentext

\Subitem{Die folgenden Aussagen beziehen sich allgemein auf Änderungsraten in einem Intervall $[a,b]$.\\

Kreuze die beiden zutreffenden Aussagen an.\\

\multiplechoice[5]{  %Anzahl der Antwortmoeglichkeiten, Standard: 5
				L1={Die größte absolute Änderung muss nicht im gleichen Intervall auftreten wie die größte relative Änderung.},   %1. Antwortmoeglichkeit 
				L2={Die relative Änderung erhält man, indem man den Quotienten der absoluten Änderung im Intervall $[a,b]$ mit $f(a)$ bildet.},   %2. Antwortmoeglichkeit
				L3={Die absolute Änderung ist immer größer als 0.},   %3. Antwortmoeglichkeit
				L4={Die relative Änderung ist immer kleiner als $100\,\%$.},   %4. Antwortmoeglichkeit
				L5={Auch wenn $f(a)=0$ ist, lässt sich die relative Änderung im Intervall $[a,b]$ berechnen.},	 %5. Antwortmoeglichkeit
				L6={},	 %6. Antwortmoeglichkeit
				L7={},	 %7. Antwortmoeglichkeit
				L8={},	 %8. Antwortmoeglichkeit
				L9={},	 %9. Antwortmoeglichkeit
				%% LOESUNG: %%
				A1=1,  % 1. Antwort
				A2=2,	 % 2. Antwort
				A3=0,  % 3. Antwort
				A4=0,  % 4. Antwort
				A5=0,  % 5. Antwort
				}
} %Unterpunkt1
\Subitem{Gegeben sind drei aufeinanderfolgende Monate $A$, $B$ und $C$. Im Monat $A$ liegt der Preis bei $a$ Cent/kWh. Die relative Änderungsrate von $A$ auf $B$ ist durch $p_1$ und jene von $B$ auf $C$ durch $p_2$ gegeben. Ermittle eine Formel zur Berechnung des Preises pro kWh für den Monat C mit Hilfe von $a$, $p_1$ und $p_2$.\\

$c=$\,\antwort[\rule{5cm}{0.3pt}]{$a\cdot(1+p_1)\cdot (1+p_2)$}} %Unterpunkt2


\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Die größte absolute Änderung fand im Zeitintervall von 07-2022 auf 08-2022 statt und beträgt 9\,155 Cent/kWh.} %Lösung von Unterpunkt1
\Subitem{Die relative Änderungsrate in diesem Intervall liegt bei $-0,2537=-25,37\%$. Dies bedeutet, dass der Preis im Vergleich zum Vormonat um rund ein Viertel gefallen ist.} %Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Wert und die (sinngemäß) richtige Deutung. Der Punkt ist dennoch zu geben, wenn der Wert richtig berechnet und gedeutet wurde, auch wenn die Angabe des Intervalls fehlt.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für den richtigen Wert und die (sinngemäß) richtige Deutung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{(siehe oben)} %Lösung von Unterpunkt1
\Subitem{(siehe oben)} %%Lösung von Unterpunkt2

