				}} %Unterpunkt1
\Subitem{Verändere eine der falschen Antwortmöglichkeiten so, dass es eine wahre Aussage wird.} %Unterpunkt2

\item Für das Zeitintervall $[0;6]$ kann der Druckverlauf mittels der Funktion\\ $p=f(t)=-\frac{1}{4}t^2+2t+2$ modelliert werden. Ab dem Zeitpunkt $t=6$ nimmt der Druck mit der zu diesem Zeitpunkt gerade gegebenen momentanen Änderungsrate gleichmäßig ab, wodurch man den Intervall $[6;10]$ mit einer linearen Funktion $p=g(t)$ modellieren kann.%Aufgabentext

\Subitem{Ermittle die momentane Druckänderung zum Zeitpunkt $t=6$.} %Unterpunkt1
\Subitem{Gib die Gleichung der linearen Funktion $p=g(t)$ an.} %Unterpunkt2
Berechne, nach wie vielen Minuten der Druck auf 0 Bar gesunken wäre, wenn sich der Druck ab dem Zeitpunkt $t=6$ gemäß der Funktion $g$ weiter entwickeln würde.
\item Wann ist der Druck im Gefäß wieder auf Normaldruck (1 bar)gesunken? .%Aufgabentext

\Subitem{Berechne das Erreichen des Normaldrucks unter der Annahme, dass der Druckverlauf mittels $p=f(t)=-\frac{1}{4}t^2+2t+2$ modelliert wird.  } %Unterpunkt1
\Subitem{Berechne das Erreichen des Normaldrucks unter der Annahme, dass der Druckverlauf nach $t=6$\,min mittels $p=g(t)$ weiterverläuft. } %Unterpunkt2


%\Subitem{XXXXGib ein Intervall an, in dem die mittlere Druckänderung pro Minute gleich Null ist.} %Unterpunkt2


\end{aufgabenstellung}


\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Momentane Druckänderung siehe Abbildung} %Lösung von Unterpunkt1
\Subitem{Zum Zeitpunkt 4 beträgt die momentane Druckänderung 0, da der Druck an dieser Stelle maximal ist.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Einzeichnen der momentanen Druckänderung (waagrechte Tangente).} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Interpretation.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Multiple Choice siehe oben} %Lösung von Unterpunkt1
\Subitem{mögliche Antworten:\\	

Innerhalb der ersten 6 Minuten beschreibt eine Funktion $f$ zweiten Grades mit $p=f(t)$ die Höhe des Drucks $p$ zur Zeit $t$.

Ab dem Zeitpunkt $t=4$ sinkt der Druck wieder.

Die absolute Änderung des Drucks im Zeitintervall $[0;2]$ beträgt 3\,Bar.
}

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtigen MC-Antworten.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine korrekte Richtigstellung.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$f'(t)=-\frac{1}{2}t+2$

	$f'(6)=-\frac{1}{2}\cdot 6+2=-1$

	$f(6)=-\frac{1}{4}\cdot 6^2+2\cdot 6+2=5 \Rightarrow (6\mid 5)$

	$y=-x+d \Rightarrow 5=-6+d \Rightarrow d=11$

	$g(t)=-x+11$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die korrekte Berechnung von $f'(6)$).} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die korrekte Gleichung} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Nach 8,9min wird Normaldruck erreicht} %Lösung von Unterpunkt1
\Subitem{Nach 11 Minuten wäre der Druck auf 0\,bar gesunken.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}


\end{loesung}

