\end{pspicture*}
\end{center}

%Aufgabentext

\Subitem{Trage in der obigen Abbildung den fehlenden Wert der Achsenbeschriftung in das dafür vorgesehene Kästchen ein.} %Unterpunkt1
\Subitem{Erstelle ein Gleichungssystem zur Berechnung der Koeffizienten $a,b$ und $c$ der Funktion $g$.} %Unterpunkt2
\Subitem{Interpretiere den nachstehenden Term im gegebenen Sachzusammenhang unter Angabe der zugehörigen Einheit.\vspace{0,3cm}

Es gilt: $t_1=2$ Tage, $t_2=42$ Tage\vspace{0,3cm}

$\dfrac{g(t_2)-f(t_1)}{t_2-t_1}$} %Unterpunkt3

\item Die Höhe einer anderen Sonnenblume lässt sich in Abhängigkeit von der Zeit $t$ in einem bestimmten Zeitintervall näherungsweise durch die Funktion $h$ beschreiben.\vspace{0,3cm}

$h(t)=6,2\cdot a^t$

$t\ldots$ Zeit ab dem Beobachtungsbeginn in Tagen\\
$h(t)\ldots$ Höhe der Sonnenblume zum Zeitpunkt $t$ in cm\vspace{0,3cm}

Zum Zeitpunkt $t=17$ beträgt die Höhe dieser Sonnenblume 38,6\,cm.

\Subitem{Berechne $a$.}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{siehe oben} %Lösung von Unterpunkt1
\Subitem{$f'(t)=\dfrac{2}{15}\cdot t+0,2$

$g'(t)=2\cdot a\cdot t+b$

$I$: $g(21)=38,6$\\
$II$: $g(42)=72,7$\\
$III$: $f'(21)=g'(21)$

oder:

$I$: $21^2\cdot a+21\cdot b+c=38,6$\\
$II$: $42^2\cdot a+42\cdot b+c=72,2$\\
$III$: $42\cdot a+b=3$} %%Lösung von Unterpunkt2
\Subitem{Der Term beschreibt die mittlere Änderungsrate der Höhe dieser Sonnenblume im Zeitintervall $[2; 42]$ in cm/Tag.

oder:

Der Term beschreibt das durchschnittliche Wachstum dieser Sonnenblume im Zeitinter­vall $[2; 42]$ in cm/Tag.} %%Lösung von Unterpunkt3

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das Eintragen des richtigen Wertes.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Erstellen des Gleichungssystems mit drei Gleichungen, ein halber Punkt für nur zwei richtige Gleichungen.} %Lösungschlüssel von Unterpunkt2
\Subitem{Ein Punkt für das richtige Interpretieren im gegebenen Sachzusammenhang unter Angabe der zugehörigen Einheit.} %Lösungschlüssel von Unterpunkt3

\item \subsection{Lösungserwartung:} 

\Subitem{$38,6=6,2\cdot a^{17}$\vspace{0,3cm}

$a=\sqrt[17]{\dfrac{38,6}{6,2}}=1,1135\ldots$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen von a.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

