Minimum: 1,5\,m\\
Median: 3\,m\\
3. Quartil: 4\,m\\
Spannweite: 5,5\,m\\
Interquartilsabstand (Differenz von 3. und 1. Quartil): 2\,m%Aufgabentext

\Subitem{Erstelle in der nachstehenden Abbildung den dadurch festgelegten Boxplot.

\begin{center}
\psset{xunit=1.3cm,yunit=1.1cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1pt,arrowsize=3pt 2,arrowinset=0.25}
