Gegeben ist eine Polynomfunktion $f$ mit $f(x)=a\cdot x^4+b\cdot x^2+c$ mit $a,b,c\in\mathbb{R}\backslash\{0\}$.%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Stelle unter Verwendung von $a$ und $b$ eine Gleichung zur Berechnung der Wendestellen von $f$ auf.} %Unterpunkt1

\item %Aufgabentext

\Subitem{Weise rechnerisch mithilfe der 1. und 2. Ableitung von $f$ nach, dass auf der senkrechten Achse ein Extrempunkt $P$ des Graphen von $f$ liegt.} %Unterpunkt1

Genau einer der Koeffizienten $a,b$ und $c$ ist ausschlaggebend dafür, ob es sich beim ermittelten Extrempunkt $P$ um einen Hochpunkt handelt.
\Subitem{\lueckentext{
				text={Damit dieser Extrempunkt $P$ ein Hochpunkt ist, muss für den Koeffizienten \gap gelten, dass dieser \gap ist.}, 	%Lueckentext Luecke=\gap
				L1={$a$}, 		%1.Moeglichkeit links  
				L2={$b$}, 		%2.Moeglichkeit links
				L3={$c$}, 		%3.Moeglichkeit links
				R1={kleiner als 0}, 		%1.Moeglichkeit rechts 
				R2={gleich 1}, 		%2.Moeglichkeit rechts
				R3={größer als 0}, 		%3.Moeglichkeit rechts
				%% LOESUNG: %%
				A1=2,   % Antwort links
				A2=1		% Antwort rechts 
				}} %Unterpunkt2

\item Gegeben ist eine Polynomfunktion $g$ mit $g(x)=d\cdot(x+e)^2\cdot(x-e)^2$ mit $d\neq 0$ und $e\in\mathbb{R}$.\\
Der Graph von $g$ verläuft durch den Punkt $N=(2\mid 0)$.%Aufgabentext

\Subitem{Ermittle unter diesen Voraussetzungen alle möglichen Werte von $e$.} %Unterpunkt1

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$f'(x)=4\cdot a\cdot x^3+2\cdot b\cdot x$\\
$f''(x)=12\cdot a\cdot x^2+2\cdot b$\\
$12\cdot a\cdot x^2+2\cdot b=0$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Gleichung.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$f'(x)=4\cdot a\cdot x^3+2\cdot b\cdot x$\\
$f'(0)=0$\\
$f''(x)=12\cdot a\cdot x^2+2\cdot b$\\
$f''(0)=2\cdot b\neq 0$

$P=(0\mid y_p)$} %Lösung von Unterpunkt1
\Subitem{siehe oben} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige rechnerische Nachweisen.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das Ankreuzen der beiden richtigen Satzteile.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$e=-2$ bzw. $e=2$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Ermitteln aller möglichen Werte von e.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

