$[0;20)$&24\\ \hline
$[20;30)$&30\\ \hline
$[30;50]$&6\\ \hline
\end{tabular}
\end{center}%Aufgabentext

\Subitem{Erstelle ein Histogramm, in dem für die drei oben angegebenen Klassen die relativen Häufigkeiten als Flächeninhalte von Rechtecken dargestellt sind.

\begin{center}
\psset{xunit=0.2cm,yunit=160cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=0.8pt,arrowsize=3pt 2,arrowinset=0.25}
