\Subitem{Begründe, warum der Median der Datenliste (die der obigen Tabelle zugrunde liegt) im Intervall $[20; 30)$ liegen muss.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$\sqrt{3\,100^2-1\,140^2}=2\,882,7\ldots$

$a=\frac{1\,140}{2\,882,7\ldots}=0,395\ldots$

$a=39,5$\,\%} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

