\item \subsection{Lösungserwartung:} 

\Subitem{siehe oben} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das Ankreuzen der beiden richtigen Satzteile, ein halber Punkt, wenn nur ein richtiger Satzteil angekreuzt ist.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{siehe oben} %Lösung von Unterpunkt1
\Subitem{Sortiert man die zugrunde liegende Datenliste aufsteigend, dann ist der Median das arithmetische Mittel des 30. und 31. Wertes. Da beide im Intervall $[20; 30)$ liegen, liegt auch das arithmetische Mittel dieser beiden Werte in diesem Intervall.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Erstellen des Histogramms.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Begründen.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

