\psplot[linewidth=2pt,plotpoints=200]{0}{10}{0.0000255433208341679*x^(6)-0.0013268773432203787*x^(5)+0.005988727938582625*x^(4)+1.1112302046391174*x^(3)-19.905115656493106*x^(2)+89.65384951122367*x}
