\end{center}%Aufgabentext

\Subitem{Ordne den vier Aussagen jeweils das passende größtmögliche Zeitintervall aus A bis F zu.

\zuordnen[0.18]{
				R1={Die Wassermenge im Teich nimmt ab.},				% Response 1
				R2={Die Wassermenge im Teich nimmt immer schneller zu.},				% Response 2
				R3={Die momentane Änderungsrate der Wassermenge im Teich nimmt ab.},				% Response 3
				R4={Die Wassermenge im Teich nimmt zu.},				% Response 4
				%% Moegliche Zuordnungen: %%
				A={$(0;3)$}, 				%Moeglichkeit A  
				B={$(3;10)$}, 				%Moeglichkeit B  
				C={$(8;12)$}, 				%Moeglichkeit C  
				D={$(3;12)$}, 				%Moeglichkeit D  
				E={$(8;10)$}, 				%Moeglichkeit E  
				F={$(0;8)$}, 				%Moeglichkeit F  
				%% LOESUNG: %%
				A1={C},				% 1. richtige Zuordnung
				A2={A},				% 2. richtige Zuordnung
				A3={B},				% 3. richtige Zuordnung
				A4={F},				% 4. richtige Zuordnung
				}} %Unterpunkt1

\end{aufgabenstellung}

\begin{loesung}
