\cellcolor[gray]{0.9}minimale Masse in kg&10&13&16&18&20&22&22&23&24&24\\ \hline
\end{tabular}

\tiny{Datenquelle: https://tierpal.de/labrador-wachstum/ [06.09.2022].}
\end{center}

Es wird angenommen, dass sich die minimale Masse von Labradorhündinnen im Alter von 1 bis 5 Monaten linear entwickelt.

\Subitem{Berechnen Sie, um wie viel Prozent die minimale Masse von Labradorhündinnen im Alter von 2 bis 3 Monaten zunimmt.}

\item Die minimale Masse von Labradorhündinnen kann für das Alter von 7 bis 15 Monaten durch die Funktion $m$: $[7;15]\rightarrow\mathbb{R}^+$ modelliert werden.\vspace{0,3cm}

$m(t)=25-24,7\cdot e^{-k\cdot t}$ mit $k\in\mathbb{R}^+$

$t\ldots$ Alter in Monaten\\
$m(t)\ldots$ minimale Masse im Alter $t$ in kg\vspace{0,3cm}

Für das Alter von 7 Monaten stimmt der Wert der Funktion $m$ mit dem entsprechenden Wert in der Tabelle überein.

Für das Alter von 12 Monaten weicht der Wert der Funktion $m$ vom entsprechenden Wert in der Tabelle ab.

\Subitem{Berechne diese Abweichung in kg.}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Oberösterreich} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Ermitteln des Bundeslands.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{"`Große Hunde"' haben im Alter von 4 Monaten eine Masse von rund 30\,kg.\\
Toleranzintervall: $[28;31]$\vspace{0,5cm}

"`Sehr große Hunde"' haben im Alter von rund 9,5 Monaten eine Masse von 80\,kg.\\
Toleranzintervall: $[9;10]$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Vervollständigen der beiden Sätze, ein halber Punkt für nur einen
richtigen Wert.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{minimale Masse im Alter von 2 Monaten: 7\,kg

$\frac{3}{7}=0,428\ldots=42,8\ldots\,\%$

Die minimale Masse von Labradorhündinnen im Alter von 2 bis 3 Monaten nimmt um rund 43\,\% zu.} %Lösung von Unterpunkt1
\Subitem{$m(7)=30$

$k=0,228\ldots$

$m(12)=23,40\ldots$

$24-m(12)=0,59\ldots$

Die Abweichung beträgt rund 0,6\,kg} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen des Prozentsatzes.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Berechnen der Abweichung, wobei $–0,6$ ebenfalls richtig ist.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

