\psellipse*[linewidth=2pt,fillcolor=black,fillstyle=solid,opacity=1](4.750432900757689,3.249567099242311)(0.05,0.05)
\psline[linewidth=0.8pt](5,0)(6,0)
\psline[linewidth=0.8pt](5,6)(6,6)
\psline[linewidth=0.8pt]{<->}(5.5,0)(5.5,6)
\parametricplot{0}{0.5404195002705842}{2*cos(t)+0|2*sin(t)+3}
\rput[tl](-0.8,3.1){eye}
\rput[bl](2.96,3.18){$r$}
\rput[bl](0.7,2.95){$\alpha$}
\rput[bl](5.62,3){$h$}
\rput[bl](1.44,3.25){$\frac{\alpha}{2}$}
\end{pspicture*}
\end{center}

\Subitem{Using $\alpha$ and $r$, write down a formula that can be used to calculate $h$.\vspace{0,5cm}

$h=\,\antwort[\rule{5cm}{0.3pt}]{2\cdot r\cdot\tan\left(\frac{\alpha}{2}\right)}$} %Unterpunkt1

\item During training, Paul shoots at 3 targets A, B, and C. His probability of hitting the target for
each shot is independent from every other shot and is given in the table below.

\begin{center}
\begin{tabular}{|l|c|c|c|}\hline
\cellcolor[gray]{0.9}target&A&B&C\\ \hline
\cellcolor[gray]{0.9}probability&$\frac{2}{5}$&$\frac{7}{10}$&$\frac{1}{4}$\\ \hline
\end{tabular}
\end{center}

Paul shoots 1 time at each of the targets A, B, and C in that order.
%Aufgabentext

\Subitem{Determine the probability that Paul hits at least 1 of these 3 targets.} %Unterpunkt1

Paul shoots 10 times at target A. The binomially distributed random variable $X$ gives the
number of hits.

\Subitem{Determine the expectation value $E(X)$.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$g$: $X=\Vek{0}{0}{1,8}+t\cdot\Vek{-5}{7}{6,7}$ mit $t\in\mathbb{R}$\vspace{0,3cm}

Die Angabe von "`$t\in\mathbb{R}$"' ist für die Punktevergabe nicht erforderlich.} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Gleichung von $g$.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$h=2\cdot r\cdot\tan\left(\frac{\alpha}{2}\right)$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Formel zur Berechnung von $h$.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$P(\text{"`Paul trifft mindestens 1 dieser 3 Ziele"'})=1-\dfrac{3}{5}\cdot\dfrac{3}{10}\cdot\dfrac{3}{4}=0,865$

Die Wahrscheinlichkeit, dass Paul mindestens 1 dieser 3 Ziele trifft, beträgt $86,5\,\%$} %Lösung von Unterpunkt1
\Subitem{$E(X)=10\cdot\dfrac{2}{5}=4$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Ermitteln von $E(X)$.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

264.content:
Bungee-Jumping ist eine Extremsportart, bei der man von einer Absprungplattform in großer
Höhe an einem elastischen Seil befestigt in die Tiefe springt.%Aufgabentext

\begin{aufgabenstellung}
\item Sabine unternimmt einen Bungeesprung. Dabei schwingt sie am Seil mehrmals auf und ab.

Ihre Höhe über dem Boden in Abhängigkeit von der Zeit $t$ wird modellhaft durch die Funktion $h$: $\mathbb{R}^+_0\rightarrow\mathbb{R}^+$ beschrieben.\vspace{0,2cm}

$h(t)=a\cdot\left(\textbf{e}^{-0,03\cdot t}\cdot\cos\left(\dfrac{\pi\cdot t}{6}\right)+1\right)$\vspace{0,2cm}

$t\ldots$ Zeit nach dem Absprung in s\\
$h(t)\ldots$ Höhe über dem Boden zum Zeitpunkt $t$ in m\\
$a\ldots$ positiver Parameter

Zum Zeitpunkt $t=0$ springt Sabine von der Absprungplattform in 90\,m Höhe über dem Boden in die Tiefe.%Aufgabentext

\Subitem{Berechne den Parameter $a$.} %Unterpunkt1

Die gesamte Zeitdauer, in der sich Sabine während des Bungeesprungs in einer Höhe von mehr als 70\,m über dem Boden befindet, wird mit $d$ bezeichnet.

\Subitem{Ermittle $d$ in Sekunden.} %Unterpunkt2

Nach Erreichen des tiefsten Punktes wird Sabine vom Seil wieder nach oben gezogen, bevor sie erneut fällt.

\Subitem{Berechne, wie viele Meter Sabine dabei nach oben gezogen wird.}

Zum Zeitpunkt $t_1$ ist Sabines (vertikale) Fallgeschwindigkeit maximal.

\Subitem{\lueckentext{
				text={Für den Zeitpunkt $t_1$ gilt \gap; die Fallgeschwindigkeit kann mit \gap berechnet werden.}, 	%Lueckentext Luecke=\gap
				L1={$h''(t_1)>0$}, 		%1.Moeglichkeit links  
				L2={$h''(t_1)<0$}, 		%2.Moeglichkeit links
				L3={$h''(t_1)=0$}, 		%3.Moeglichkeit links
				R1={$h(t_1)$}, 		%1.Moeglichkeit rechts 
				R2={$\big|h'(t_1)\big|$}, 		%2.Moeglichkeit rechts
				R3={$\dint^{t_1}_0 h(t)\dx[t]$}, 		%3.Moeglichkeit rechts
				%% LOESUNG: %%
				A1=3,   % Antwort links
				A2=2		% Antwort rechts 
				}}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$h(0)=a\cdot\left(\textbf{e}^{-0,03\cdot 0}\cdot\cos\left(\dfrac{\pi\cdot 0}{6}\right)+1\right)=90$

$2\cdot a=90$

$a=45$} %Lösung von Unterpunkt1
\Subitem{$h(t)=70$

Berechnung mittels Technologieeinsatz:

$t_1=1,803\ldots$\quad$t_2=10,663\ldots$\quad$t_3=13,149\ldots$\\
$d=t_1+(t_3-t_2)=4,289\ldots$} %%Lösung von Unterpunkt2

\Subitem{$h'(t)=0$

Berechnung mittels Technologieeinsatz:

lokales Minimum: $T_1=(5,890\ldots\mid 7,351\ldots)$\\
lokale Maximum: $H_1=(11,890\ldots\mid 76,446\ldots)$\\
$76,446\ldots-7,351\ldots=69,095\ldots$

Sabine wird rund 69,1\,m nach oben gezogen, bevor sie erneut fällt.}

\Subitem{siehe oben}

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen von $a$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Ermitteln von $d$.} %Lösungschlüssel von Unterpunkt2
\Subitem{Ein Punkt für das richtige Berechnen.}
\Subitem{Ein Punkt für das Ankreuzen der beiden richtigen Satzteile, ein halber Punkt, wenn nur ein
richtiger Satzteil angekreuzt ist.}

\end{loesung}

264.content_translation:
Bungee jumping is an extreme sport in which a person is attached to an elastic rope and jumps off of a platform at a great height.%Aufgabentext

\begin{aufgabenstellung}
\item Sabine undertakes a bungee jump. During the jump, she bounces up and down a number of times. 

Her height above the ground can be modelled in terms of the time $t$ by the function $h$: $\mathbb{R}^+_0\rightarrow\mathbb{R}^+$.\vspace{0,2cm}

$h(t)=a\cdot\left(\textbf{e}^{-0{.}03\cdot t}\cdot\cos\left(\dfrac{\pi\cdot t}{6}\right)+1\right)$\vspace{0,2cm}

