\multips(0,0)(1,0){9}{\psline[linestyle=dashed,linecap=1,dash=1.5pt 1.5pt,linewidth=0.4pt,linecolor=lightgray]{c-c}(0,0)(0,5.9819121447028465)}
\psaxes[labelFontSize=\scriptstyle,xAxis=true,yAxis=true,labels=y,Dx=1,Dy=1,ticksize=-2pt 0,subticks=0]{->}(0,0)(0,0)(7.8,5.9819121447028465)[x,140] [y,-40]
\pspolygon[linewidth=1.2pt,fillcolor=black,fillstyle=solid,opacity=0.1](1,5.5)(3,5.5)(3,0)(1,0)
\pspolygon[linewidth=1.2pt,fillcolor=black,fillstyle=solid,opacity=0.1](3,2.5)(5,2.5)(5,0)(3,0)
\pspolygon[linewidth=1.2pt,fillcolor=black,fillstyle=solid,opacity=0.1](5,2.5)(5,4)(6,4)(6,0)(5,0)
\rput[tl](0.8,-0.25){61}
\rput[tl](1.8,-0.25){62}
\rput[tl](2.8,-0.25){63}
\rput[tl](3.8,-0.25){64}
\rput[tl](4.8,-0.25){65}
\rput[tl](5.8,-0.25){66}
\end{pspicture*}} %Lösung von Unterpunkt1

\Subitem{Derzeit ist der Median der Mittelwert aus dem 10. und 11. Wert, also aus 62,6 und 62,6. Nach Hinzufügen eines höheren 21. Wertes stellt der 11. Wert den Median dar, also weiterhin die Zahl 62,6.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{4}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für ein entsprechendes Histogramm} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine entsprechende Begründung.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

