\rput[tl](9,-0.2){$2$}
\end{scriptsize}
\rput[tl](4.82,3.49){$v$}
\end{pspicture*}
\end{center} %Aufgabentext


\Subitem{Interpret the area of the region shaded grey in the diagram above in the given context.} %Unterpunkt1

2\,min after the start of the dive, Laurin reaches a diving depth of 16\,m.

\Subitem{Determine $c$.} %Unterpunkt2

\Subitem{Determine the time interval for which Laurin’s vertical velocity is at least 9\,m/min.} %Unterpunkt2


\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$p(d)=98\cdot d+930$} %Lösung von Unterpunkt1

