	\end{center}%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Zeige, dass für den Flächeninhalt $A(x)$ einer derartigen Schwimmzone die Gleichung $A(x)=180\cdot x-2\cdot x^2$ gilt. Benutze dazu die Skizze! } %Unterpunkt1
\Subitem{Löse die Gleichung $A(x)=180\cdot x-2\cdot x^2$ für einen Flächeninhalt von $2250 \,m^{2}$. Schreibe die Umformungen der Gleichung auf! \vspace{0,5cm}

\textbf{1. Möglichkeit:}\vspace{0,2cm}

	Länge = \antwort[\rule{3cm}{0.3pt}]{30}\,m\quad und \quad Breite = \antwort[\rule{3cm}{0.3pt}]{75}\,m\vspace{0,5cm}

	\textbf{2. Möglichkeit:}\vspace{0,2cm}

	Länge = \antwort[\rule{3cm}{0.3pt}]{150}\,m\quad und \quad Breite = \antwort[\rule{3cm}{0.3pt}]{15}\,m} %Unterpunkt2

\Subitem{Schreibe eine Formel für die Seillänge auf und führe die Probe für die Lösungen aus dem vorigen Punkt durch. Schreibe die Rechenschritte auf.\vspace{0,5cm}

	Formel Seillänge = \antwort[\rule{3cm}{0.3pt}]{ $2 x + (180-2 x)$ }\,m\vspace{0,5cm}

	Seillänge für Lösung \textbf{1. Möglichkeit} (von Aufgabe a2) = \antwort[\rule{3cm}{0.3pt}]{180}\,m\vspace{0,5cm}

	Seillänge für Lösung \textbf{2. Möglichkeit} (von Aufgabe a2) = \antwort[\rule{3cm}{0.3pt}]{180}\,m\vspace{0,5cm}}

\item Angenommen die Fläche entspricht $2q$ ($A=2q$).

\Subitem{Wähle $2q$ so, dass die Gleichung für die Fläche ($A(x)=180\cdot x-2\cdot x^2$) nur eine Lösung hat. Schreibe die Lösungsschritte für die Gleichung auf und berechne den gesuchten Flächeninhalt.\vspace{0,5cm}

Flächeninhalt = \antwort[\rule{3cm}{0.3pt}]{4\,050}\,m$^2$}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$x\cdot(180-2x)=180x-2x^2$} %Lösung von Unterpunkt1
\Subitem{$2\,250=180x-2x^2$\quad$\Rightarrow$\quad$x_1=15$, $x_2=75$

Längen und Breiten siehe oben.} %%Lösung von Unterpunkt2
\Subitem{siehe oben} %%Lösung von Unterpunkt3

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine entsprechende Herleitung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtigen Werte.} %Lösungschlüssel von Unterpunkt2
\Subitem{Ein Punkt für die richtige Formel sowie die entsprechenden Seillängen.} %Lösungschlüssel von Unterpunkt3

\item \subsection{Lösungserwartung:} 

\Subitem{$2q=180x-2x^2$\quad$\Rightarrow$\quad$\left(\frac{90}{2}\right)^2-q=0$\quad$\Rightarrow$\quad $q=2\,025$

$A=2q=2\cdot 2\,025=4\,050$\,m$^2$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Berechnung des Flächeninhalts.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

