\begin{pspicture*}(-6.79,-0.2)(6.79,4.8)
\psplot[linewidth=0.8pt]{-6.79}{6.79}{(-0-0*x)/8}
\psline[linewidth=1pt]{->}(-4,0)(-4,1)
\psline[linewidth=1pt]{->}(-3.5,1.9364916731037085)(-3.0158770817240725,2.8114916731037085)
\psline[linewidth=1pt]{->}(-2.1988186949430717,3.341436270044492)(-1.3634596274319493,3.8911409437802598)
\psline[linewidth=1pt]{->}(-0.5,4)(0.5,4)
\psline[linewidth=1pt]{->}(1.5,3.7080992435478315)(2.4270248108869574,3.333099243547832)
\psline[linewidth=1pt]{->}(4,1)(4,0)
\psline[linewidth=1pt]{->}(2.9956915117458123,2.6506286738157216)(3.658348680199743,1.901705795879268)
