\rput[tl](-1,4.6){maximale Höhe}
\rput[tl](3,3.5){gleitender Abstieg}
\rput[tl](4.35,0.7){Landung}
\rput[tl](-5,0.7){Start}
\rput[tl](-5.73,3.5){gleitender Aufstieg}
\end{scriptsize}
\end{pspicture*}
\end{center}

%Aufgabentext

\begin{aufgabenstellung}
\item Die Startgeschwindigkeit der Raketer beträgt $v_0=30$\,m/s. Gesucht ist der Zeitpunkt nachdem die Rakete die Höhe $h=25$\,m erreicht.%Aufgabentext

\Subitem{Setze $h$ und $v_0$ in die Formel ein und löse die quadratische Gleichung für $t$. Schreibe alle notwendigen Rechenschritte auf.} %Unterpunkt1
\Subitem{Begründe warum die Gleichung zwei Lösungen hat und gib an ob beide Lösungen im gegebenen Kontext sinnvoll sind.} %Unterpunkt2

\item Gegeben ist die allgemeine Gleichung $h = - 5 \cdot t^{2} + 30 \cdot t$.

\Subitem{Gib an, bei welcher Höhe die Gleichung nur eine Lösung besitzt. Schreibe alle notwendigen Rechenschritte auf.}

\Subitem{Interpretiere diese Flughöhe im gegebenen Kontext.}

\item 

\Subitem{Löse die Gleichung $h = - 5 \cdot t^{2} + 30 \cdot t$ für die Flughöhe von 200\,m.}

\Subitem{Begründe mathematisch, warum die Flughöhe nicht erreicht wird.}

\item Gegeben ist die Gleichung $ h = - 5 \cdot t^{2} + v_{0} \cdot t $.

\Subitem{Gib an, wie groß die Startgeschwindigkeit $v_0$ sein muss, damit die Raketer nach $t=10$\,s wieder den Erdboden erreicht. Schreibe alle notwendigen Rechenschritte auf.}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$t_1=1$\,s; $t_2=5$\,s} %Lösung von Unterpunkt1
\Subitem{Die Rakete erreicht die Höhe sowohl beim Auf- wie auch beim Abstieg.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtigen Werte.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine entsprechende Interpretation.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$h=45$\,m} %Lösung von Unterpunkt1
\Subitem{Es handelt sich dabei um die höchste Flughöhe der Rakete.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Höhe.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine entsprechende Interpretation.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$t=3\pm\sqrt{9-40}\notin\mathbb{R}$} %Lösung von Unterpunkt1
\Subitem{Die Diskriminante wird negativ, daher existieren keine Lösungen in $\mathbb{R}$. Die Flughöhe wird nie erreicht.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine entsprechende Berechnung.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine entsprechende Interpretation.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$50$\,m/s} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für den richtigen Wert.} %Lösungschlüssel von Unterpunkt1

\end{loesung}

