Die im Monat Mai benötigte Energie kann durch $\dint^5_4r(t)\dx[t]$ berechnet werden.

\Subitem{\lueckentext{
				text={Für die benötigte Energie gilt \gap und \gap.}, 	%Lueckentext Luecke=\gap
				L1={$\dint^5_4 r(t)\dx[t]<\dint^8_7 r(t)\dx[t]$}, 		%1.Moeglichkeit links  
				L2={$\dint^5_4 r(t)\dx[t]>\dint^{10}_9 r(t)\dx[t]$}, 		%2.Moeglichkeit links
				L3={$\dint^5_4 r(t)\dx[t]>\dint^7_8 r(t)\dx[t]$}, 		%3.Moeglichkeit links
