				R2={$\dint^5_4 r(t)\dx[t]<\dfrac{\dint^{6}_0 r(t)\dx[t]}{6}$}, 		%2.Moeglichkeit rechts
				R3={$\dint^5_4 r(t)\dx[t]<\dfrac{\dint^{7}_4 r(t)\dx[t]}{3}$}, 		%3.Moeglichkeit rechts
				%% LOESUNG: %%
				A1=3,   % Antwort links
