%Aufgabentext

\Subitem{\lueckentext{
				text={Die Menge des Wirkstoffs A in Herrn Winters Körper um 13:00 ist \gap die Menge des Wirkstoffs A in Herrn Winters Körper um 7:00 Uhr; in Herrn Winters Körper beträgt die Halbwertszeit des Wirkstoffs A \gap.}, 	%Lueckentext Luecke=\gap
				L1={gleich groß wie}, 		%1.Moeglichkeit links  
				L2={kleiner als}, 		%2.Moeglichkeit links
				L3={größer als}, 		%3.Moeglichkeit links
				R1={2\,h}, 		%1.Moeglichkeit rechts 
				R2={3\,h}, 		%2.Moeglichkeit rechts
				R3={6\,h}, 		%3.Moeglichkeit rechts
				%% LOESUNG: %%
				A1=3,   % Antwort links
				A2=1		% Antwort rechts 
				}} %Unterpunkt1

\item Frau Egger bekommt zum Zeitpunkt $t=0$ den Wirkstoff B verabreicht.\\
Die reelle Funktion $m_B$ mit $m_B(t)=1,019\cdot t\cdot e^{-0,025\cdot t}$ beschreibt modellhaft die Menge des Wirkstoffs B in Frau Eggers Körper in Abhängigkeit von der Zeit ($t$ in min, $m_B(t)$ in mg).

Ab dem Zeitpunkt $t=240$\,min kann die Menge des Wirkstoffs B in Frau Eggers Körper in Abhängigkeit von der Zeit $t$ modellhaft durch die lineare Funktion $f$ beschrieben werden ($t$ in min, $f(t)$ in mg).

Die Funktionen $m_B$ und $f$ haben an der Stelle $t=240$\,min den gleichen Funktionswert und die gleiche Steigung. %Aufgabentext

\Subitem{Stelle eine Funktionsgleichung von $f$ auf.\vspace{0,5cm}

$f(t)=\,\antwort[\rule{3cm}{0.3pt}]{-0,0126\ldots\cdot t+3,6372\ldots}$} %Unterpunkt1	

\item Die Wahrscheinlichkeit, dass nach der Einnahme des Wirkstoffs C Übelkeit als Nebenwirkung auftritt, beträgt 14\,\%.

Es werden $n$ Personen, die den Wirkstoff C eingenommen haben, nach dem Zufallsprinzip ausgewählt. Die Anzahl derjenigen Personen, bei denen Übelkeit als Nebenwirkung auftritt, wird als binomialverteilt angenommen.%Aufgabentext

\Subitem{Interpretieren Sie die nachstehende Ungleichung im gegebenen Sachzusammenhang.

$1-0,86^n\geq 0,90$} %Unterpunkt1

Die Wahrscheinlichkeit, dass nach der Einnahme des Wirkstoffs C Müdigkeit als Nebenwirkung auftritt, beträgt $a$.\\
Die Nebenwirkungen Müdigkeit und Übelkeit treten unabhängig voneinander auf.

Die Wahrscheinlichkeit, dass sowohl Müdigkeit als auch Übelkeit als Nebenwirkung auftreten, beträgt 0,0126.

\Subitem{Berechne $a$.\vspace{0,5cm}

$a=\,\antwort[\rule{3cm}{0.3pt}]{0,09}$} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{siehe oben} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein halber Punkt für das Ankreuzen des ersten richtigen Satzteils, ein halber Punkt für das Ankreuzen des zweiten richtigen Satzteils.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{$f(t)=k\cdot t+d$

$m_B(240)=f(240)=0,6062\ldots$

$m'_B(240)=f'(240)=-0,0126\ldots$

Berechnung mittels Technologieeinsatz:

$f(t)=-0,0126\ldots\cdot t+3,6372\ldots$} %Lösung von Unterpunkt1

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Aufstellen der Funktionsgleichung von $f$.} %Lösungschlüssel von Unterpunkt1

\item \subsection{Lösungserwartung:} 

\Subitem{Die Wahrscheinlichkeit, dass bei mindestens 1 der $n$ ausgewählten Personen Übelkeit als Nebenwirkung auftritt, beträgt mindestens 90\,\%.} %Lösung von Unterpunkt1
\Subitem{$a=0,09$} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Interpretieren im gegebenen Sachzusammenhang.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Berechnen von $a$.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

