\psline[linewidth=1.2pt](11.121320343559642,13.121320343559642)(9,15.242640687119284)
\psline[linewidth=1.2pt](9,15.242640687119284)(6,15.242640687119284)
\psline[linewidth=1.2pt](6,15.242640687119284)(3.8786796564403585,13.121320343559642)
\psline[linewidth=1.2pt](3.8786796564403585,13.121320343559642)(3.8786796564403576,10.121320343559644)
