\rput[bl](-5.2,5.105432033816072){$g_1$}
\end{scriptsize}
\end{pspicture*}
\end{center}

Es gilt:

$g_1(x)=k_1\cdot x+d_1$ mit $-6\leq x\leq -3$\\
$g_2(x)=k_2\cdot x+d_2$ mit $3\leq x\leq 6$\\
$f(x)=-0,5\cdot x^2+10$ mit $-2\leq x\leq 2$

$x, f(x), g_1(x), g_2(x)\ldots$ Maße in Längeneinheiten (LE)\\
$k_1, k_2, d_1, d_2,\ldots$ reelle Parameter\vspace{0,5cm}

Der größere Teil des Logos wird von den Graphen der Funktionen $g_1$ und $g_2$ und zwei weiteren Strecken sowie von einem Halbkreis mit dem Mittelpunkt $M=(0\mid 0)$ und dem Radius  $r=6$\,LE begrenzt.

Der kleinere Teil des Logos wird vom Graphen der Funktion $f$ und von zwei Strecken begrenzt und ist in der Abbildung grau markiert dargestellt.

Die Eckpunkte des größeren Teils des Logos haben ganzzahlige Koordinaten.

\Subitem{Berechnen Sie den Anteil $p_A$ des Flächeninhalts der grau markierten Fläche am gesamten Flächeninhalt des Logos in Prozent.}

\Subitem{\lueckentext{
				text={Für die Funktionen $g_1$ und $g_2$ gilt: \gap und \gap.}, 	%Lueckentext Luecke=\gap
				L1={$k_1=-k_2$}, 		%1.Moeglichkeit links  
				L2={$k_1=k_2$}, 		%2.Moeglichkeit links
				L3={$k_1=-\frac{1}{k_2}$}, 		%3.Moeglichkeit links
				R1={$d_1=-d_2$}, 		%1.Moeglichkeit rechts 
				R2={$d_1=d_2$}, 		%2.Moeglichkeit rechts
				R3={$d_1=-\frac{1}{d_2}$}, 		%3.Moeglichkeit rechts
				%% LOESUNG: %%
				A1=1,   % Antwort links
				A2=2		% Antwort rechts 
				}}

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{$G(x)=p\cdot x-\left(\dfrac{x^3}{10^6}-\dfrac{15\cdot x^2}{10^4}+1,5\cdot x+1\,000\right)$

$G'(1\,500)=0$\vspace{0,5cm}

Berechnung mittels Technologieeinsatz:

$p=3,75$} %Lösung von Unterpunkt1
\Subitem{Der Funktionsgraph der Kostenfunktion und der Funktionsgraph der Gewinnfunktion werden durch die (Änderung der) Fixkosten nur in vertikaler Richtung verschoben. (Daher ist die Maximumstelle der Gewinnfunktion unabhängig von den Fixkosten.)

\textit{oder:}

Beim Ableiten der Gewinnfunktion fällt derjenige Koeffizient weg, der sich aus den Fixkosten ergibt. (Daher ist die Maximumstelle der Gewinnfunktion unabhängig von den Fixkosten.)} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen von $p$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für das richtige Begründen.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{Flächeninhalt der grau markierten Fläche: $2\cdot\left(\dint^2_0 f(x)\dx-12\right)=\dfrac{40}{3}$\vspace{0,5cm}

$p_a=\dfrac{\frac{40}{3}}{\frac{40}{3}+18\cdot\pi+72}$\vspace{0,5cm}

$p_A=9,39\ldots\,\%$} %Lösung von Unterpunkt1
\Subitem{siehe oben} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für das richtige Berechnen von $p_A$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein halber Punkt für das Ankreuzen des ersten richtigen Satzteils, ein halber Punkt für das Ankreuzen des zweiten richtigen Satzteils.} %Lösungschlüssel von Unterpunkt2

\end{loesung}

