1717.content:
Löse die Gleichung und kürze, wenn möglich, die Lösung!

$$\dfrac{1}{2}+x:\dfrac{5}{6}=\dfrac{9}{10}$$

\antwort{\begin{align*}
x:\dfrac{5}{6}&=\dfrac{9}{10}-\dfrac{1}{2}\\
x:\dfrac{5}{6}&=\dfrac{9}{10}-\dfrac{5}{10}\\
x:\dfrac{5}{6}&=\dfrac{4}{10}\\
x&=\dfrac{4}{10}\cdot\dfrac{5}{6}\\
x&=\dfrac{1}{3}
\end{align*}}

1718.content:
Löse die Gleichung und kürze, wenn möglich, die Lösung!

$$\dfrac{1}{4}+x\cdot\dfrac{4}{3}=\dfrac{79}{60}$$

\antwort{\begin{align*}
x\cdot\dfrac{4}{3}&=\dfrac{79}{60}-\dfrac{1}{4}\\
x\cdot\dfrac{4}{3}&=\dfrac{79}{60}-\dfrac{15}{60}\\
x\cdot\dfrac{4}{3}&=\dfrac{64}{60}\\
x&=\dfrac{64}{60}:\dfrac{4}{3}\\
x&=\dfrac{64}{60}\cdot\dfrac{3}{4}\\
x&=\dfrac{4}{5}
\end{align*}}

1719.content:
Löse die Gleichung und kürze, wenn möglich, die Lösung!

$$\dfrac{1}{2}:x-\dfrac{1}{4}=\dfrac{5}{4}$$

\antwort{\begin{align*}
\dfrac{1}{2}:x&=\dfrac{5}{4}+\dfrac{1}{4}\\
\dfrac{1}{2}:x&=\dfrac{6}{4}\\
\dfrac{1}{2}&=\dfrac{6}{4}\cdot x\\
\dfrac{1}{2}:\dfrac{6}{4}&=x\\
\dfrac{1}{2}\cdot\dfrac{4}{6}&=x\\
x&=\dfrac{1}{3}
\end{align*}}

1720.content:
Löse die Gleichung und kürze, wenn möglich, die Lösung!

$$\dfrac{3}{5}\cdot x+\dfrac{1}{4}=\dfrac{7}{20}$$

\antwort{\begin{align*}
\dfrac{3}{5}\cdot x&=\dfrac{7}{20}-\dfrac{1}{4}\\
\dfrac{3}{5}\cdot x&=\dfrac{7}{20}-\dfrac{5}{20}\\
\dfrac{3}{5}\cdot x&=\dfrac{2}{20}\\
x&=\dfrac{1}{10}:\dfrac{3}{5}\\
x&=\dfrac{1}{10}\cdot\dfrac{5}{3}\\
x&=\dfrac{1}{6}
\end{align*}}

1721.content:
Löse die Gleichung und kürze, wenn möglich, die Lösung!

$$\dfrac{5}{9}+x\cdot\dfrac{2}{3}=1$$

\antwort{\begin{align*}
x\cdot\dfrac{2}{3}&=1-\dfrac{5}{9}\\
x\cdot\dfrac{2}{3}&=\dfrac{9}{9}-\dfrac{5}{9}\\
x\cdot\dfrac{2}{3}&=\dfrac{4}{9}\\
x&=\dfrac{4}{9}:\dfrac{2}{3}\\
x&=\dfrac{4}{9}\cdot\dfrac{3}{2}\\
x&=\dfrac{2}{3}
\end{align*}}

1722.content:
Löse die Gleichung und kürze, wenn möglich, die Lösung!

$$\dfrac{8}{3}:x-\dfrac{5}{3}=0$$

\antwort{\begin{align*}
\dfrac{8}{3}:x&=\dfrac{5}{3}\\
\dfrac{8}{3}&=\dfrac{5}{3}\cdot x\\
\dfrac{8}{3}:\dfrac{5}{3}&=x\\
\dfrac{8}{3}\cdot\dfrac{3}{5}&=x\\
x&=\dfrac{8}{5} 
\end{align*}}

