5679.content:
Gegeben ist das rechtwinklige Dreieck $ABC$ mit $c$ als Hypotenuse.

$b=5,6$\,cm; $c=6,5$\,cm

\begin{itemize}
\item Konstruiere das gegebene rechtwinklige Dreieck.
\item Berechne die Länge der fehlenden Seite (gib die notwendigen Rechenschritte an).
\item Berechne den Flächeninhalt.
\item Berechne die Höhe $h_b$ auf die Seite $b$ (gib die notwendigen Rechenschritte an).
\end{itemize}

\antwort{\begin{center}
\psset{xunit=1cm,yunit=1cm,algebraic=true,dimen=middle,dotstyle=o,dotsize=5pt 0,linewidth=1pt,arrowsize=3pt 2,arrowinset=0.25}
\begin{pspicture*}(-0.36,-7.82)(7.28,-3.72)
\psline[linewidth=1pt](0.16,-7.28)(6.66,-7.28)
\psline[linewidth=1pt](6.66,-7.28)(4.984615384615385,-4.436923076923078)
\psline[linewidth=1pt](4.984615384615385,-4.436923076923078)(0.16,-7.28)
\begin{scriptsize}
\psdots[dotstyle=*](0.16,-7.28)
\rput[bl](-0.12,-7.62){$A$}
\psdots[dotstyle=*](6.66,-7.28)
\rput[bl](6.8,-7.66){$B$}
\rput[bl](3.42,-7.64){$c$}
\psdots[dotstyle=*](4.984615384615385,-4.436923076923078)
\rput[bl](5.06,-4.24){$C$}
\rput[bl](5.96,-5.76){$a$}
\rput[bl](2.4,-5.66){$b$}
\end{scriptsize}
\end{pspicture*}
\end{center}

$a=\sqrt{c^2-b^2}=\sqrt{6,5^2-5,6^2}=3,3$\,cm\vspace{0,3cm}

$A=\dfrac{a\cdot b}{2}=\dfrac{3,3\cdot 5,6}{2}=9,24$\,cm$^2$\vspace{0,3cm}

$A=\dfrac{b\cdot h_b}{2}\Rightarrow h_b=\dfrac{2\cdot A}{b}=\dfrac{2\cdot 9,24}{5,6}=3,3$\,cm}

