\antwort{\begin{itemize}
\item $a=\sqrt{h_c^2+\left(\frac{c}{2}\right)^2}=\sqrt{74,8^2+19,5^2}=77,3$\,cm
\item $A=\dfrac{c\cdot h_c}{2}=\dfrac{39\cdot 74,8}{2}=1\,458,6$\,cm$^2$
\item $h_a=\dfrac{2\cdot A}{a}=\dfrac{2\cdot 1\,458,6}{77,3}=37,73868\approx 37,74$\,cm
\end{itemize}}

