Berechne die Länge der Diagonalen $e$ und $f$ sowie den Flächeninhalt des gegebenen Parallelogramms.

\antwort{\begin{itemize}
\item $m=\sqrt{b^2-h_a^2}=\sqrt{7,7^2-5,9^2}\approx 4,95$\,cm

\item $f=\sqrt{h_a^2+(a-m)^2}=\sqrt{5,9^2+(6,8-4,95)^2}\approx 6,18$\,cm

\item $e=\sqrt{h_a^2+(a+m)^2}=\sqrt{5,9^2+(6,8+4,95)^2}\approx 13,15$\,cm

\item $A=a\cdot h_a=6,8\cdot 5,9=40,12$\,cm$^2$
\end{itemize}
}

