\pscustom[linewidth=1.pt,fillcolor=black,fillstyle=solid,opacity=0.2]{\parametricplot{2.199114857512855}{2.827433388230814}{1.*3.*cos(t)+0.*3.*sin(t)+0.|0.*3.*cos(t)+1.*3.*sin(t)+0.}\lineto(0.,0.)\closepath}
\pscustom[linewidth=1.pt,fillcolor=black,fillstyle=solid,opacity=0.3]{\parametricplot{2.827433388230814}{5.340707511102648}{1.*3.*cos(t)+0.*3.*sin(t)+0.|0.*3.*cos(t)+1.*3.*sin(t)+0.}\lineto(0.,0.)\closepath}
\pscustom[linewidth=1.pt,fillcolor=black,fillstyle=solid,opacity=0.4]{\parametricplot{-0.9424777960769379}{0.0}{1.*3.*cos(t)+0.*3.*sin(t)+0.|0.*3.*cos(t)+1.*3.*sin(t)+0.}\lineto(0.,0.)\closepath}
\rput[tl](0.24,1.6){WA}
\rput[tl](-2.,1.36){SC}
\rput[tl](-1.26,-0.92){YT}
\rput[tl](1.5,-0.72){TT}
\end{pspicture*}
\end{center}

%Aufgabentext

\begin{aufgabenstellung}
\item %Aufgabentext

\Subitem{Lies aus dem gegebenen Kreisdiagramm ab, wie viel Prozent der gesamten Bildschirmzeit am Vortag auf die App TikTok entfielen.} %Unterpunkt1

Bedirhan hat am Vortag insgesamt 16 Minuten auf der App \textit{Snapchat} verbracht. Der zugehörige Winkel im Kreisdiagramm sind 36$^\circ$.

\Subitem{Berechne wie viele Minuten Bedirhan gestern sein Handy insgesamt verwendet hat (insgesamte Bildschirmzeit).} %Unterpunkt2

\item Bedirhan stellt fest, dass er in letzter Zeit zu viel Zeit mit seinem Handy verbringt. Dinge, die ihm wichtig sind – draußen Zeit mit Freunden zu verbringen oder den neuen Band seiner Fantasyreihe weiterzulesen – bleiben dabei oft auf der Strecke. Eine Auswertung zeigt, dass seine durchschnittliche tägliche Bildschirmzeit letzte Woche bei 155 Minuten lag. Für die kommende Woche nimmt er sich vor, diesen Wert deutlich zu reduzieren. Am Ende der Woche hat er es geschafft, die durchschnittliche tägliche Bildschirmzeit auf 124 Minuten zu senken.%Aufgabentext

\Subitem{Berechne um wie viel Prozent sich die durchschnittliche tägliche Bildschirmzeit von Bedirhan im Vergleich zur vorherigen Woche \textbf{verringert} hat.} %Unterpunkt1

Bedirhan ist sehr zufrieden mit sich. Stolz erzählt er seiner Mutter, dass er es diese Woche geschafft habe, an keinem einzigen Tag mehr als 124 Minuten auf seinem Handy zu verbringen – schließlich lag seine durchschnittliche Bildschirmzeit genau bei diesem Wert.

\Subitem{Erkläre, warum diese Aussage vermutlich nicht ganz korrekt ist.} %Unterpunkt2

\end{aufgabenstellung}

\begin{loesung}
\item \subsection{Lösungserwartung:} 

\Subitem{Der Winkel des Kreissektors von (TT) beträgt $54^\circ$, deshalb: $54^\circ:3,6=15\,\%$

15\,\% der Bildschirmzeit entfiel auf die App Tik-Tok} %Lösung von Unterpunkt1
\Subitem{24 Minuten entsprechen 15\,\% also entsprechen 1,6 Minuten genau 1\,\%.

Bedirhan hat also am Vortag 160 Minuten auf seinem Handy verbracht.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für eine richtige Prozentzahl. Alle Winkel zwischen $[53^\circ;55^\circ]$ sind zulässig, damit auch alle Prozentzahlen zwischen $[14,7\,\%;15,3\,\%]$.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für die richtige Minutenanzahl wobei wenn mit einem falschen Ergebnis von (a1) richtig gerechnet wird es auch gezählt wird.} %Lösungschlüssel von Unterpunkt2

\item \subsection{Lösungserwartung:} 

\Subitem{$p=\dfrac{A\cdot 100}{G}=\dfrac{124\cdot 100}{155}=80\,\%$

Bedirhan hat also im Schnitt um 20\,\% weniger Zeit am Handy verbracht.} %Lösung von Unterpunkt1
\Subitem{Da es sich bei den 124 Minuten um einen Durchschnittswert handelt wird es Tage geben an denen er mehr Zeit am Handy verbracht hat und Tage an denen er weniger Zeit verbracht hat.} %%Lösung von Unterpunkt2

\setcounter{subitemcounter}{0}
\subsection{Lösungsschlüssel:}

\Subitem{Ein Punkt für die richtige Prozentzahl.} %Lösungschlüssel von Unterpunkt1
\Subitem{Ein Punkt für eine entsprechende Argumentation} %Lösungschlüssel von Unterpunkt2

\end{loesung}

